/* Three Kingdoms timeline data, in English and Simplified Chinese.
   The backbone for 155-220 is the Annals of Emperor Wu (《三国志·魏书·武帝纪》), Cao Cao's own annals,
   followed year by year; later steps follow the other annals and biographies of the Records.
   Each step: id/y (year), yr (label), era (reign title), own (province changes from the step before),
   nm (faction renames), zh/en {t: title, x: text}, q (a quotation: s = source, c = original, en = translation).
   Quotations are from Chen Shou's text unless the source says Pei Songzhi's notes or another work. */
window.TK_DATA = {
  steps: [
    { id: '155', y: 155, yr: '155', era: '永寿元年',
      own: { liang: 'han', bing: 'han', sili: 'han', ji: 'han', you: 'han', liaodong: 'han', qing: 'han', yan: 'han', xu: 'han', yu: 'han', huainan: 'han', jiangdong: 'han', jingN: 'han', jingS: 'han', hanzhong: 'han', yi: 'han', jiao: 'han' },
      zh: { t: '曹操出生', x: '汉桓帝在位，宦官势力如日中天。这一年，曹操出生于沛国谯县。他的家世是一生的软肋：养祖父曹腾是历事四帝的宦官，官至中常侍、大长秋，封费亭侯；父亲曹嵩是曹腾的养子，生父是谁，陈寿说已无从查考。《武帝纪》没有写他的生年，155年是由他去世时“年六十六”倒推出来的。' },
      en: { t: 'Cao Cao is born', x: 'Emperor Huan reigns and the palace eunuchs are at the height of their power. Cao Cao is born in Qiao county, Pei. His ancestry will dog him all his life: his grandfather by adoption, Cao Teng, was a eunuch who served four emperors and was made a marquis, and his father Cao Song was Cao Teng’s adopted son, whose real parentage Chen Shou says no one could trace. The annals give no birth year; 155 is worked back from his age at death.' },
      q: { s: '《武帝纪》', c: '太祖武皇帝，沛国谯人也，姓曹，讳操，字孟德，汉相国参之后。桓帝世，曹腾为中常侍大长秋，封费亭侯。养子嵩嗣，官至太尉，莫能审其生出本末。', en: 'Emperor Wu was a man of Qiao in Pei, surnamed Cao, named Cao, styled Mengde, a descendant of the Han chancellor Cao Can. In Emperor Huan’s reign Cao Teng was a palace attendant and was enfeoffed as Marquis of Feiting. His adopted son Song succeeded him and rose to Grand Commandant; no one could establish where he came from.' } },

    { id: '174', y: 174, yr: '174', era: '熹平三年',
      own: {},
      zh: { t: '洛阳北部尉', x: '汉灵帝在位。166年和169年两次“党锢之祸”之后，大批士人被禁锢终身，宦官把持朝政。年轻的曹操被举为孝廉，进入仕途。' },
      en: { t: 'A young officer in the capital', x: 'Emperor Ling reigns. After the Proscriptions of 166 and 169 barred hundreds of scholar-officials from office for life, the eunuchs run the court. The young Cao Cao is recommended as “filial and incorrupt” and enters government.' },
      q: { s: '《武帝纪》', c: '年二十，举孝廉为郎，除洛阳北部尉，迁顿丘令，征拜议郎。', en: 'At twenty he was recommended as filial and incorrupt and made a gentleman, then appointed Commandant of the Northern District of Luoyang; he was transferred to magistrate of Dunqiu, and summoned back as a Consultant.' } },

    { id: '184', y: 184, yr: '184', era: '中平元年',
      own: {},
      zh: { t: '黄巾起义', x: '巨鹿人张角以“太平道”传教十余年，信众遍布青、徐、幽、冀、荆、扬、兖、豫八州。184年，三十六方同日起事，头裹黄巾。朝廷解除党锢，派皇甫嵩、朱儁、卢植分路镇压，当年即击破主力，但各地余部和随之而起的“黑山”等武装延续多年。为平乱，朝廷允许地方募兵，种下了割据的根。' },
      en: { t: 'The Yellow Turbans', x: 'For over a decade Zhang Jue of Julu had preached his “Way of Great Peace” across eight provinces. In 184 his thirty-six districts rose on the same day, wearing yellow headscarves. The court lifted the proscriptions and sent Huangfu Song, Zhu Jun and Lu Zhi against them; the main armies were broken within the year, but remnants and new bands such as the Black Mountain bandits fought on for years. To fight them the court let local officials raise their own troops, planting the seeds of the warlords.' },
      q: { s: '《武帝纪》', c: '光和末，黄巾起。拜骑都尉，讨颍川贼。', en: 'At the end of the Guanghe era the Yellow Turbans rose. He was made Chief Commandant of Cavalry and attacked the rebels in Yingchuan.' } },

    { id: '187', y: 187, yr: '187–188', era: '中平四至五年',
      own: { liang: 'mateng', yi: 'liuzhang' },
      nm: { mateng: ['Han Sui, Ma Teng', '韩遂、马腾'], liuzhang: ['Liu Yan', '刘焉'] },
      zh: { t: '废史立牧', x: '凉州边章、韩遂自184年起反叛，屡败官军，西北从此脱离朝廷控制。188年，宗室刘焉建议改刺史为州牧，赋予地方长官军政大权，自己出任益州牧。同年，灵帝在西园设置八校尉，以宦官蹇硕为首，曹操也在其中。' },
      en: { t: 'Governors with armies', x: 'Since 184 Bian Zhang and Han Sui had been in revolt in Liang province, beating every army sent against them; the north-west slipped out of the court’s hands. In 188 Liu Yan, a member of the imperial clan, persuaded the court to turn provincial inspectors into governors with full military powers, and took Yi province for himself. The same year Emperor Ling created eight Colonels of the Western Garden under the eunuch Jian Shuo, Cao Cao among them.' },
      q: { s: '《武帝纪》', c: '顷之，冀州刺史王芬、南阳许攸、沛国周旌等连结豪杰，谋废灵帝，立合肥侯，以告太祖，太祖拒之。芬等遂败。', en: 'Soon after, Wang Fen, Inspector of Ji, with Xu You of Nanyang, Zhou Jing of Pei and others, gathered powerful men and plotted to depose Emperor Ling in favour of the Marquis of Hefei. They told Cao Cao, who refused. Wang Fen and the rest were destroyed.' } },

    { id: '189', y: 189, yr: '189', era: '中平六年',
      own: { sili: 'dong' },
      zh: { t: '董卓入京', x: '四月灵帝驾崩，少帝刘辩即位，何太后临朝。大将军何进与袁绍谋诛宦官，召董卓等外兵进京施压，事未成而何进被宦官所杀，袁绍等随即攻入宫中尽诛宦官。董卓入洛阳，收编何进兄弟部曲，九月废少帝为弘农王，立陈留王刘协为帝，即汉献帝。袁绍出奔冀州。' },
      en: { t: 'Dong Zhuo takes the capital', x: 'Emperor Ling dies in the fourth month; his son Liu Bian succeeds with the Empress Dowager He as regent. The commander-in-chief He Jin and Yuan Shao plan to wipe out the eunuchs and summon Dong Zhuo’s frontier army to frighten the court. The eunuchs kill He Jin first; Yuan Shao storms the palace and kills every eunuch he can find. Dong Zhuo enters Luoyang, absorbs He Jin’s troops, and in the ninth month deposes the boy and enthrones his half-brother Liu Xie, Emperor Xian. Yuan Shao flees to Ji.' },
      q: { s: '《武帝纪》', c: '卓表太祖为骁骑校尉，欲与计事。太祖乃变易姓名，间行东归。', en: 'Dong Zhuo recommended Cao Cao as Colonel of Courageous Cavalry, wanting to plan affairs with him. Cao Cao changed his name and slipped away east by back roads.' } },

    { id: '190', y: 190, yr: '190', era: '初平元年',
      own: { liaodong: 'gongsundu', jingN: 'liubiao', jingS: 'liubiao' },
      zh: { t: '关东联军', x: '正月，袁术、韩馥、孔伷、刘岱、王匡、袁绍、张邈、桥瑁、袁遗、鲍信等同时起兵，推袁绍为盟主，讨伐董卓。董卓挟献帝西迁长安，焚毁洛阳宫室，掘陵取宝。联军各怀心思，屯兵不进，只有曹操和长沙太守孙坚真正与董军交战。同年，公孙度据辽东自立，刘表单骑入荆州，平定宗贼，成为荆州之主。' },
      en: { t: 'The eastern coalition', x: 'In the first month Yuan Shu, Han Fu, Kong Zhou, Liu Dai, Wang Kuang, Yuan Shao, Zhang Miao, Qiao Mao, Yuan Yi and Bao Xin all raise troops against Dong Zhuo and make Yuan Shao their leader. Dong Zhuo moves the emperor west to Chang’an, burns the palaces of Luoyang and loots the imperial tombs. The coalition lords sit in their camps; only Cao Cao and Sun Jian, Administrator of Changsha, actually fight Dong’s armies. Gongsun Du makes himself master of Liaodong, and Liu Biao rides alone into Jing and takes control of it.' },
      q: { s: '《武帝纪》', c: '到荥阳汴水，遇卓将徐荣，与战不利，士卒死伤甚多。太祖为流矢所中，所乘马被创，从弟洪以马与太祖，得夜遁。', en: 'At the Bian River near Xingyang he met Dong Zhuo’s general Xu Rong and was defeated, with heavy losses. He was hit by a stray arrow and his horse was wounded; his cousin Cao Hong gave him his own horse, and he escaped by night.' } },

    { id: '191', y: 191, yr: '191', era: '初平二年',
      own: { ji: 'yuanshao', hanzhong: 'zhanglu' },
      zh: { t: '袁绍夺冀州', x: '联军瓦解。袁绍逼迫冀州牧韩馥让出冀州，成为北方最强的诸侯；公孙瓒在幽州与袁绍对峙。孙坚在阳人大破董卓军，斩华雄，进入洛阳，随后奉袁术之命攻打刘表，在襄阳附近中伏身亡（一说在192年）。五斗米道首领张鲁占据汉中，断绝斜谷道路。' },
      en: { t: 'Yuan Shao takes Ji', x: 'The coalition falls apart. Yuan Shao bullies Han Fu into handing over Ji province and becomes the strongest lord in the north, facing Gongsun Zan in You. Sun Jian routs Dong Zhuo’s army at Yangren, kills Hua Xiong and enters Luoyang; then, sent by Yuan Shu against Liu Biao, he is ambushed and killed near Xiangyang (some accounts say in 192). Zhang Lu, leader of the Five Pecks of Rice sect, seizes Hanzhong and cuts the roads.' },
      q: { s: '《武帝纪》', c: '袁绍因表太祖为东郡太守，治东武阳。', en: 'Yuan Shao then recommended Cao Cao as Administrator of Dong commandery, with his seat at Dongwuyang.' } },

    { id: '192', y: 192, yr: '192', era: '初平三年',
      own: { sili: 'lijue', yan: 'cao' },
      zh: { t: '董卓之死与青州兵', x: '四月，司徒王允与吕布刺杀董卓。董卓部将李傕、郭汜随即攻破长安，杀王允，赶走吕布，挟持献帝。青州黄巾百万之众涌入兖州，兖州刺史刘岱战死，曹操由此入主兖州。' },
      en: { t: 'Dong Zhuo dies; the Qingzhou army', x: 'In the fourth month Minister Wang Yun and Lü Bu assassinate Dong Zhuo. Dong’s generals Li Jue and Guo Si storm Chang’an, kill Wang Yun, drive out Lü Bu and take the emperor prisoner. A million Yellow Turbans from Qing pour into Yan province and kill its inspector Liu Dai, which opens the way for Cao Cao to take Yan.' },
      q: { s: '《武帝纪》', c: '冬，受降卒三十余万，男女百余万口，收其精锐者，号为青州兵。', en: 'In winter he accepted the surrender of over 300,000 soldiers and more than a million men and women, and took the best of them as the Qingzhou army.' } },

    { id: '193', y: 193, yr: '193', era: '初平四年',
      own: { you: 'gongsun', huainan: 'yuanshu' },
      zh: { t: '征讨陶谦', x: '袁术北上进攻兖州，被曹操在匡亭击败，南逃九江，据有淮南。公孙瓒在幽州杀害了深得人心的幽州牧刘虞，独霸幽州。曹操的父亲曹嵩避难琅琊，在徐州牧陶谦境内遇害。' },
      en: { t: 'War on Tao Qian', x: 'Yuan Shu marches north into Yan and is beaten by Cao Cao at Kuangting; he flees south to Jiujiang and takes Huainan. In You, Gongsun Zan kills the popular governor Liu Yu and rules alone. Cao Cao’s father Cao Song, sheltering in Langya, is killed in the territory of Tao Qian, governor of Xu.' },
      q: { s: '《武帝纪》', c: '秋，太祖征陶谦，下十余城，谦守城不敢出。', en: 'In autumn he attacked Tao Qian and took more than ten cities; Tao Qian shut himself in and dared not come out.' } },

    { id: '194', y: 194, yr: '194', era: '兴平元年',
      own: { xu: 'liubei', jiao: 'shixie' },
      nm: { liuzhang: ['Liu Zhang', '刘璋'] },
      zh: { t: '兖州之变', x: '曹操再征徐州，后方的张邈、陈宫迎吕布入兖州，各郡县纷纷响应，曹操几乎失去全部根据地。这一年关东大旱、蝗灾，粮价飞涨，人相食。陶谦病死，临终把徐州托付给刘备。益州牧刘焉去世，其子刘璋继位。' },
      en: { t: 'Yan rises against Cao Cao', x: 'While Cao Cao is again attacking Xu, Zhang Miao and Chen Gong invite Lü Bu into Yan, and nearly every county goes over to him; Cao Cao almost loses everything. Drought and locusts hit the east, grain prices soar and people eat each other. Tao Qian dies and leaves Xu to Liu Bei. In Yi, Liu Yan dies and his son Liu Zhang succeeds him.' },
      q: { s: '《武帝纪》', c: '是岁谷一斛五十余万钱，人相食，乃罢吏兵新募者。', en: 'That year a measure of grain cost over 500,000 cash and people ate each other, so he dismissed the newly recruited officers and soldiers.' } },

    { id: '195', y: 195, yr: '195', era: '兴平二年',
      own: { jiangdong: 'sun' },
      nm: { sun: ['Sun Ce', '孙策'] },
      zh: { t: '收复兖州', x: '曹操连败吕布，吕布东奔刘备。长安城内李傕、郭汜火并，献帝趁乱东归，一路被追杀，渡过黄河到达安邑。孙策向袁术借兵渡江，横扫丹阳、吴郡，开始建立江东基业。' },
      en: { t: 'Yan recovered', x: 'Cao Cao beats Lü Bu again and again, and Lü Bu flees east to Liu Bei. In Chang’an Li Jue and Guo Si turn on each other; Emperor Xian escapes east, pursued all the way, and crosses the Yellow River to Anyi. Sun Ce borrows troops from Yuan Shu, crosses the Yangtze and sweeps through Danyang and Wu: the start of his realm in the south-east.' },
      q: { s: '《武帝纪》', c: '冬十月，天子拜太祖兖州牧。十二月，雍丘溃，超自杀。夷邈三族。', en: 'In the tenth month the emperor appointed him Governor of Yan. In the twelfth month Yongqiu fell and Zhang Chao killed himself. Zhang Miao’s family was exterminated to the third degree.' } },

    { id: '196', y: 196, yr: '196', era: '建安元年',
      own: { yu: 'cao', sili: 'cao', xu: 'lubu', qing: 'yuanshao' },
      zh: { t: '迎天子都许', x: '七月，献帝在杨奉、韩暹护送下回到残破的洛阳，百官“披荆棘，依墙壁间”。曹操入洛护驾，九月迁都许县。从此他“奉天子以令不臣”，以朝廷名义发号施令。吕布趁刘备与袁术交战，袭取下邳，夺了徐州。袁绍之子袁谭夺取青州。' },
      en: { t: 'The emperor comes to Xu', x: 'In the seventh month Emperor Xian, escorted by Yang Feng and Han Xian, reaches the ruins of Luoyang, where officials camp among the brambles and broken walls. Cao Cao comes to guard him and in the ninth month moves the court to his own base at Xu. From now on he gives orders in the emperor’s name. Lü Bu seizes Xiapi and the province of Xu while Liu Bei is fighting Yuan Shu. Yuan Shao’s son Yuan Tan takes Qing.' },
      q: { s: '《武帝纪》', c: '是岁用枣祗、韩浩等议，始兴屯田。', en: 'That year, on the advice of Zao Zhi, Han Hao and others, he began the military farm colonies.' } },

    { id: '197', y: 197, yr: '197', era: '建安二年',
      own: {},
      zh: { t: '宛城之败', x: '张绣在宛城先降后叛，曹操惨败，长子曹昂战死。袁术在寿春称帝，国号“仲家”，奢靡无度，众叛亲离，孙策也与他断绝关系。' },
      en: { t: 'Defeat at Wan', x: 'Zhang Xiu surrenders at Wan, then turns on Cao Cao and routs him; Cao Cao’s eldest son Cao Ang is killed. Yuan Shu proclaims himself emperor at Shouchun. His extravagance drives his followers away, and Sun Ce breaks with him.' },
      q: { s: '《武帝纪》', c: '公与战，军败，为流矢所中，长子昂、弟子安民遇害。', en: 'He fought and was defeated, hit by a stray arrow; his eldest son Ang and his nephew Anmin were killed.' } },

    { id: '198', y: 198, yr: '198', era: '建安三年',
      own: {},
      zh: { t: '白门楼', x: '曹操东征吕布，围下邳，引泗水、沂水灌城。建安三年十二月（公历已是199年初），吕布部将缚陈宫出降，吕布被擒处死。同年，长安的李傕被朝廷所遣部将诛杀，关中诸将名义上归附曹操。' },
      en: { t: 'The end of Lü Bu', x: 'Cao Cao marches on Lü Bu, besieges Xiapi and floods it from the Si and Yi rivers. In the twelfth month of the year (early 199 by the Western calendar) Lü Bu’s officers tie up Chen Gong and open the gates; Lü Bu is captured and executed. Li Jue is killed in Chang’an the same year, and the warlords of the Wei valley submit to Cao Cao in name.' },
      q: { s: '《武帝纪》', c: '月余，布将宋宪、魏续等执陈宫，举城降，生禽布、宫，皆杀之。', en: 'After more than a month Lü Bu’s generals Song Xian and Wei Xu seized Chen Gong and surrendered the city. Lü Bu and Chen Gong were taken alive, and both were killed.' } },

    { id: '199', y: 199, yr: '199', era: '建安四年',
      own: { you: 'yuanshao', huainan: 'cao', xu: 'liubei' },
      zh: { t: '大战前夜', x: '袁绍在易京围杀公孙瓒，统一河北四州，拥兵十余万，准备南下。袁术走投无路，北投袁谭，途中病死。刘备奉命截击袁术，却在下邳杀死曹操任命的徐州刺史车胄，据徐州反曹。曹操分兵把守官渡，迎接决战。' },
      en: { t: 'On the eve of war', x: 'Yuan Shao destroys Gongsun Zan at Yijing and holds all four provinces north of the Yellow River, with over 100,000 troops, ready to march south. Yuan Shu, out of options, heads north to join Yuan Tan and dies on the way. Liu Bei, sent to intercept him, instead kills Cao Cao’s inspector of Xu at Xiapi and rebels. Cao Cao garrisons Guandu and waits for the clash.' },
      q: { s: '《武帝纪》', c: '程昱、郭嘉闻公遣备，言于公曰：「刘备不可纵。」公悔，追之不及。', en: 'When Cheng Yu and Guo Jia heard Cao Cao had sent Liu Bei away, they told him: “Liu Bei must not be let loose.” He regretted it and sent after him, too late.' } },

    { id: '200', y: 200, yr: '200', era: '建安五年',
      own: { xu: 'cao' },
      nm: { sun: ['Sun Quan', '孙权'] },
      zh: { t: '官渡之战', x: '正月，“衣带诏”谋诛曹操之事败露，车骑将军董承等被杀。曹操东征击溃刘备，随后在白马、延津连斩袁绍大将颜良、文丑，又在官渡与袁绍主力相持半年。十月，袁绍谋士许攸来投，曹操夜袭乌巢，焚其粮草，袁军崩溃。同年，孙策遇刺身亡，十八岁的孙权继位。' },
      en: { t: 'Guandu', x: 'In the first month the “girdle edict” plot to kill Cao Cao is exposed, and General Dong Cheng and others are executed. Cao Cao smashes Liu Bei in the east, then kills Yuan Shao’s generals Yan Liang and Wen Chou at Baima and Yanjin, and holds Yuan’s main army at Guandu for half a year. In the tenth month Yuan’s adviser Xu You defects; Cao Cao raids Wuchao by night, burns the grain, and Yuan’s army collapses. Sun Ce is assassinated and Sun Quan, 18, succeeds him.' },
      q: { s: '《武帝纪》', c: '时公兵不满万，伤者十二三。', en: 'At the time his troops numbered fewer than ten thousand, and two or three in ten were wounded.' } },

    { id: '201', y: 201, yr: '201', era: '建安六年',
      own: {},
      zh: { t: '仓亭', x: '曹操在仓亭再败袁绍。刘备在汝南联合黄巾余部作乱，曹操南征，刘备投奔荆州刘表，屯驻新野。' },
      en: { t: 'Cangting', x: 'Cao Cao beats Yuan Shao again at Cangting. Liu Bei stirs up Yellow Turban remnants in Runan; when Cao Cao marches south, he flees to Liu Biao in Jing and is stationed at Xinye.' },
      q: { s: '《武帝纪》', c: '绍之未破也，使刘备略汝南，汝南贼共都等应之。', en: 'Before Yuan Shao was beaten, he had sent Liu Bei to raid Runan, and the Runan bandit Gong Du and others joined him.' } },

    { id: '202', y: 202, yr: '202', era: '建安七年',
      own: {},
      nm: { yuanshao: ['Yuan Tan, Yuan Shang', '袁谭、袁尚'] },
      zh: { t: '袁绍之死', x: '五月，袁绍发病呕血而死。他偏爱幼子袁尚，未立长子袁谭，两兄弟各拥部众，河北陷入内斗。' },
      en: { t: 'Yuan Shao dies', x: 'In the fifth month Yuan Shao dies, vomiting blood. He had favoured his youngest son Yuan Shang over his eldest, Yuan Tan, and the two brothers each hold on to their own followers. The north turns on itself.' },
      q: { s: '《武帝纪》', c: '吾起义兵，为天下除暴乱。旧土人民，死丧略尽，国中终日行，不见所识，使吾凄怆伤怀。', en: '“I raised a loyal army to rid the world of tyranny. The people of my home district are almost all dead. I walk through it all day and see no one I know. It fills me with grief.”' } },

    { id: '203', y: 203, yr: '203', era: '建安八年',
      own: {},
      zh: { t: '二袁相争', x: '曹操攻破黎阳，袁谭、袁尚退守邺城。曹操听从郭嘉的建议佯攻刘表，任由兄弟相残；袁谭被袁尚打败，反向曹操求援。' },
      en: { t: 'Brother against brother', x: 'Cao Cao takes Liyang and the Yuan brothers fall back on Ye. On Guo Jia’s advice he turns south as if to attack Liu Biao and lets the brothers fight; beaten by Yuan Shang, Yuan Tan asks Cao Cao for help.' },
      q: { s: '《武帝纪》', c: '谭、尚争冀州，谭为尚所败，走保平原。', en: 'Tan and Shang fought over Ji; Tan was beaten by Shang and fled to hold Pingyuan.' } },

    { id: '204', y: 204, yr: '204', era: '建安九年',
      own: { ji: 'cao' },
      zh: { t: '邺城', x: '曹操围攻袁氏的根据地邺城，掘壕四十里，引漳水灌城，城中饿死者过半。八月城破，守将审配宁死不降。曹操从此以邺城为根据地，自领冀州牧。' },
      en: { t: 'The fall of Ye', x: 'Cao Cao besieges Ye, the Yuan family’s capital, digs a forty-li trench and floods the city from the Zhang River; more than half the people inside starve. In the eighth month the city falls; its commander Shen Pei refuses to surrender and is executed. Ye becomes Cao Cao’s capital and he takes the governorship of Ji.' },
      q: { s: '《武帝纪》', c: '公临祀绍墓，哭之流涕；慰劳绍妻，还其家人宝物，赐杂缯絮，廪食之。', en: 'He went to sacrifice at Yuan Shao’s tomb and wept; he comforted Yuan Shao’s widow, returned her family’s treasures, and gave them silk, floss and an allowance of grain.' } },

    { id: '205', y: 205, yr: '205', era: '建安十年',
      own: { qing: 'cao', you: 'cao' },
      zh: { t: '冀州平定', x: '正月，曹操在南皮斩杀袁谭。幽州的袁熙部将焦触等叛降，袁熙、袁尚逃往乌桓。河北大部平定，黑山军首领张燕率十余万众归降。' },
      en: { t: 'The north-east settled', x: 'In the first month Cao Cao kills Yuan Tan at Nanpi. Yuan Xi’s officers in You defect, and Yuan Xi and Yuan Shang flee to the Wuhuan. Most of the north is now Cao Cao’s; Zhang Yan of the Black Mountain bandits surrenders with over 100,000 followers.' },
      q: { s: '《武帝纪》', c: '令民不得复私雠，禁厚葬，皆一之于法。', en: 'He ordered that the people must no longer take private vengeance, banned lavish burials, and brought everything under the law.' } },

    { id: '206', y: 206, yr: '206', era: '建安十一年',
      own: { bing: 'cao' },
      zh: { t: '并州', x: '袁绍的外甥、并州刺史高干反叛，据守壶关。曹操亲征，壶关投降，高干南逃途中被杀，并州平定。' },
      en: { t: 'Bing province', x: 'Gao Gan, Yuan Shao’s nephew and inspector of Bing, rebels and holds Huguan Pass. Cao Cao marches against him; Huguan surrenders, Gao Gan is killed fleeing south, and Bing is taken.' } },

    { id: '207', y: 207, yr: '207', era: '建安十二年',
      own: {},
      zh: { t: '北征乌桓', x: '曹操远征塞外的乌桓，在白狼山大破敌军，斩其单于蹋顿。袁尚、袁熙逃往辽东，被公孙康斩首送来，袁氏覆灭，北方统一。同年冬，刘备三顾茅庐，见到了隐居隆中的诸葛亮。' },
      en: { t: 'Beyond the Wall', x: 'Cao Cao marches beyond the Great Wall against the Wuhuan, routs them at White Wolf Mountain and kills their chieftain Tadun. Yuan Shang and Yuan Xi flee to Liaodong, where Gongsun Kang cuts off their heads and sends them to Cao Cao. The Yuan family is finished and the north is united. In winter Liu Bei calls three times on Zhuge Liang at Longzhong.' },
      q: { s: '《武帝纪》', c: '八月，登白狼山，卒与虏遇，众甚盛。……公登高，望虏阵不整，乃纵兵击之，使张辽为先锋，虏众大崩，斩蹋顿及名王已下，胡、汉降者二十余万口。', en: 'In the eighth month he climbed White Wolf Mountain and suddenly met the enemy in great numbers. Climbing high, he saw their ranks were in disorder, and sent his troops in with Zhang Liao leading. The enemy broke; Tadun and his chiefs were killed, and over 200,000 Wuhuan and Han surrendered.' } },

    { id: '208', y: 208, yr: '208', era: '建安十三年',
      own: { jingN: 'cao', jingS: 'cao' },
      zh: { t: '赤壁之战', x: '六月，汉朝废三公，曹操出任丞相。八月，孔融被杀（见《后汉书·孔融传》）。七月曹操南征，刘表病死，其子刘琮举荆州投降，刘备南逃。诸葛亮出使江东，孙权决意抗曹，派周瑜、程普率军西上，与刘备联军在赤壁击败曹军。曹操北还，留曹仁守江陵。' },
      en: { t: 'Red Cliffs', x: 'In the sixth month the Han abolishes its three senior ministries and Cao Cao becomes Chancellor. In the eighth the scholar Kong Rong is executed (Book of the Later Han). Cao Cao marches south; Liu Biao dies and his son Liu Cong surrenders Jing, and Liu Bei flees. Zhuge Liang goes to Sun Quan, who decides to fight and sends Zhou Yu and Cheng Pu up the Yangtze. With Liu Bei they defeat Cao Cao at Red Cliffs. Cao Cao goes north, leaving Cao Ren in Jiangling.' },
      q: { s: '《武帝纪》', c: '公至赤壁，与备战，不利。于是大疫，吏士多死者，乃引军还。', en: 'He reached Red Cliffs and fought Liu Bei without success. Then a great epidemic broke out, many officers and men died, and he led his army back. (This is all Cao Cao’s annals say about the battle.)' } },

    { id: '209', y: 209, yr: '209', era: '建安十四年',
      own: { jingS: 'liubei' },
      zh: { t: '荆州易手', x: '周瑜围攻江陵一年有余，曹仁弃城北撤。刘备南征武陵、长沙、桂阳、零陵四郡，被推为荆州牧，治公安，并娶孙权之妹。曹操在谯县训练水军，进驻合肥。' },
      en: { t: 'Jing changes hands', x: 'Zhou Yu besieges Jiangling for over a year until Cao Ren abandons it. Liu Bei takes the four southern commanderies of Wuling, Changsha, Guiyang and Lingling, is acclaimed governor of Jing with his seat at Gong’an, and marries Sun Quan’s sister. Cao Cao trains a navy at Qiao and moves to Hefei.' },
      q: { s: '《武帝纪》', c: '秋七月，自涡入淮，出肥水，军合肥。', en: 'In the seventh month he went from the Guo River into the Huai, out by the Fei, and camped at Hefei.' } },

    { id: '210', y: 210, yr: '210', era: '建安十五年',
      own: { jiao: 'sun' },
      zh: { t: '唯才是举', x: '周瑜在准备西取益州时病逝，年三十六，鲁肃接任，主张借荆州南郡给刘备共拒曹操。孙权派步骘为交州刺史，士燮兄弟归附东吴。曹操发布《求贤令》，在邺城修建铜雀台。' },
      en: { t: 'Talent above all', x: 'Zhou Yu dies at 36 while preparing to march on Yi. His successor Lu Su argues for lending Nan commandery in Jing to Liu Bei so the two can hold off Cao Cao together. Sun Quan sends Bu Zhi to govern Jiao, and Shi Xie and his brothers submit to Wu. Cao Cao issues his edict seeking talent and builds the Bronze Bird Terrace at Ye.' },
      q: { s: '《武帝纪》', c: '若必廉士而后可用，则齐桓其何以霸世！……二三子其佐我明扬仄陋，唯才是举，吾得而用之。', en: '“If only men of spotless integrity could be employed, how could Duke Huan of Qi have become overlord of the world? Help me find those of humble station: talent is the only test, and I will use them.”' } },

    { id: '211', y: 211, yr: '211', era: '建安十六年',
      own: {},
      nm: { mateng: ['Ma Chao, Han Sui', '马超、韩遂'] },
      zh: { t: '潼关之战', x: '曹操派钟繇、夏侯渊借道关中讨伐汉中张鲁，关中诸将疑心是冲着自己来的，马超、韩遂等十部起兵，屯守潼关。曹操亲征，渡渭水后用贾诩的离间计，大破关中联军。同年，刘璋迎刘备入蜀，共拒张鲁。' },
      en: { t: 'Tong Pass', x: 'Cao Cao sends Zhong Yao and Xiahou Yuan through the Wei valley against Zhang Lu in Hanzhong. The warlords of the valley suspect they are the real target; Ma Chao, Han Sui and eight others rebel and hold Tong Pass. Cao Cao takes the field, crosses the Wei River, sows distrust between them on Jia Xu’s advice, and crushes them. Liu Zhang invites Liu Bei into Yi to help against Zhang Lu.' },
      q: { s: '《武帝纪》', c: '公与遂交马语移时，不及军事，但说京都旧故，拊手欢笑。', en: 'Cao Cao and Han Sui talked for a long time from horseback, not about the war but about old friends in the capital, clapping their hands and laughing. (Ma Chao, watching, began to suspect Han Sui.)' } },

    { id: '212', y: 212, yr: '212', era: '建安十七年',
      own: {},
      zh: { t: '荀彧之死', x: '献帝准许曹操“赞拜不名，入朝不趋，剑履上殿”。在许都的马腾因马超反叛被诛灭三族。董昭等人谋划为曹操晋爵魏公、加九锡，曹操最重要的谋臣荀彧表示反对，随即在随军途中死于寿春。陈寿说他“以忧薨”，裴注引《魏氏春秋》则说他收到曹操送来的空食盒后服毒自尽：“曹操赐死荀彧”一说即源于此。年底，刘备与刘璋决裂，回军攻打成都。' },
      en: { t: 'The death of Xun Yu', x: 'The emperor allows Cao Cao to be announced without his name, to walk rather than hurry at court, and to wear his sword and shoes in the hall. Ma Teng, held in the capital, is executed with his family because of Ma Chao’s revolt. When Dong Zhao and others push to make Cao Cao Duke of Wei with the Nine Bestowments, his most important adviser, Xun Yu, objects, and soon dies at Shouchun while with the army. Chen Shou says he died of worry; a later source quoted by Pei Songzhi says Cao Cao sent him an empty food box and he took poison. That is where the story of Cao Cao ordering his death comes from. At the end of the year Liu Bei turns on Liu Zhang.' },
      q: { s: '《荀彧传》；裴注引《魏氏春秋》', c: '太祖由是心不能平。会征孙权，表请彧劳军于谯，因辄留彧……彧疾留寿春，以忧薨，时年五十。／《魏氏春秋》：太祖馈彧食，发之乃空器也，于是饮药而卒。', en: 'Chen Shou: “From then on Cao Cao was uneasy with him. During the campaign against Sun Quan he asked for Xun Yu to come and reward the army at Qiao, and kept him there… Xun Yu fell ill and stayed at Shouchun, where he died of worry, aged fifty.” The Spring and Autumn Annals of Wei, quoted by Pei: “Cao Cao sent Xun Yu food; when he opened it the vessel was empty, and he drank poison and died.”' } },

    { id: '213', y: 213, yr: '213', era: '建安十八年',
      own: {},
      zh: { t: '魏公与九锡', x: '曹操进攻濡须口，与孙权相持月余后撤军。朝廷合并十四州为九州，扩大冀州，以冀州十郡建立魏国。五月，献帝策命曹操为魏公，加九锡；七月建魏国社稷宗庙，献帝又聘曹操的三个女儿为贵人。刘备围攻雒城。' },
      en: { t: 'Duke of Wei', x: 'Cao Cao attacks Ruxu and withdraws after a month’s stand-off with Sun Quan. The court merges the fourteen provinces into nine, enlarging Ji, and carves ten of its commanderies into the state of Wei. In the fifth month the emperor names Cao Cao Duke of Wei with the Nine Bestowments; in the seventh the altars and ancestral temple of Wei are built, and the emperor takes three of Cao Cao’s daughters as consorts. Liu Bei besieges Luo.' },
      q: { s: '《武帝纪》', c: '五月丙申，天子使御史大夫郗虑持节策命公为魏公。', en: 'On the bingshen day of the fifth month the emperor sent the Imperial Counsellor Xi Lü with the staff of authority to invest him as Duke of Wei.' } },

    { id: '214', y: 214, yr: '214', era: '建安十九年',
      own: { liang: 'cao', yi: 'liubei' },
      zh: { t: '伏皇后之死；刘备入成都', x: '夏侯渊平定陇右，马超投奔张鲁后又归刘备，凉州平定。夏天，刘备攻下雒城，成都投降，刘璋被迁往荆州。十一月，伏皇后多年前写给父亲伏完、说献帝怨恨曹操的书信被揭发，皇后被废，幽禁而死，兄弟皆被处死。' },
      en: { t: 'An empress dies; Liu Bei takes Chengdu', x: 'Xiahou Yuan pacifies the far west; Ma Chao flees to Zhang Lu and then to Liu Bei, and Liang is Cao Cao’s. In summer Liu Bei takes Luo, Chengdu surrenders and Liu Zhang is sent away to Jing. In the eleventh month a letter Empress Fu had written years before to her father, saying the emperor resented Cao Cao, comes to light. She is deposed and dies in confinement, and her brothers are executed.' },
      q: { s: '《武帝纪》', c: '十一月，汉皇后伏氏坐昔与父故屯骑校尉完书，云帝以董承被诛怨恨公，辞甚丑恶，发闻，后废黜死，兄弟皆伏法。', en: 'In the eleventh month the Han empress, of the Fu family, was charged over a letter she had once written to her father, the former colonel Fu Wan, saying the emperor resented Cao Cao for the execution of Dong Cheng, in very ugly words. When it came out she was deposed and died, and her brothers were all executed.' } },

    { id: '215', y: 215, yr: '215', era: '建安二十年',
      own: { hanzhong: 'cao' },
      zh: { t: '汉中、合肥与湘水之盟', x: '正月，曹操之女曹节被立为皇后。曹操西征张鲁，攻破阳平关，张鲁投降，汉中归曹。孙权趁机率十万大军攻合肥，被张辽、李典以七千守军击败。孙刘为荆州几乎开战，最终以湘水为界平分：长沙、江夏、桂阳归吴，南郡、零陵、武陵归刘备。' },
      en: { t: 'Hanzhong, Hefei and the Xiang River', x: 'In the first month Cao Cao’s daughter Cao Jie is made empress. Cao Cao marches on Zhang Lu, breaks through Yangping Pass and Zhang Lu surrenders: Hanzhong is his. Sun Quan seizes the moment to attack Hefei with 100,000 men and is beaten by Zhang Liao and Li Dian with a garrison of 7,000. Sun and Liu nearly go to war over Jing and split it along the Xiang River: Changsha, Jiangxia and Guiyang to Wu, Nan, Lingling and Wuling to Liu Bei.' },
      q: { s: '《武帝纪》', c: '冬十一月，鲁自巴中将其余众降。封鲁及五子皆为列侯。', en: 'In the eleventh month Zhang Lu came out of Bazhong with the rest of his followers and surrendered. Zhang Lu and his five sons were all made marquises.' } },

    { id: '216', y: 216, yr: '216', era: '建安二十一年',
      own: {},
      zh: { t: '魏王', x: '五月，献帝晋封曹操为魏王，距离帝位只差一步。南匈奴单于呼厨泉来朝，被留在邺城，由右贤王去卑回去监国。尚书崔琰被告发书信中有讽刺之意，先被罚作徒隶，后被赐死（《崔琰传》）。' },
      en: { t: 'King of Wei', x: 'In the fifth month the emperor raises Cao Cao to King of Wei, one step from the throne. Huchuquan, chanyu of the Southern Xiongnu, comes to court and is kept at Ye while the Wise King of the Right, Qubei, governs his people. The minister Cui Yan is accused of mockery in a letter, sentenced to hard labour, and then ordered to kill himself (Biography of Cui Yan).' },
      q: { s: '《武帝纪》', c: '夏五月，天子进公爵为魏王。', en: 'In the fifth month the emperor raised his rank from duke to King of Wei.' } },

    { id: '217', y: 217, yr: '217', era: '建安二十二年',
      own: {},
      zh: { t: '立太子与大疫', x: '曹操再攻濡须，孙权派都尉徐详求和请降，双方重修旧好。鲁肃去世，吕蒙接掌长江上游的兵权。十月，曹丕被立为魏太子，曹植在继承之争中落败。这一年大疫流行，建安七子中的王粲、徐干、陈琳、应玚、刘桢相继去世。' },
      en: { t: 'An heir, and a plague', x: 'Cao Cao attacks Ruxu again; Sun Quan sends Xu Xiang to sue for peace and offer submission, and the two renew their ties. Lu Su dies and Lü Meng takes over Wu’s upriver command. In the tenth month Cao Pi is named Crown Prince of Wei: his brother Cao Zhi has lost the contest to succeed. An epidemic sweeps the north; five of the Seven Masters of the Jian’an era, Wang Can, Xu Gan, Chen Lin, Ying Yang and Liu Zhen, die.' },
      q: { s: '曹丕《与吴质书》', c: '昔年疾疫，亲故多离其灾，徐、陈、应、刘，一时俱逝。', en: 'Cao Pi, in a letter to Wu Zhi: “In that year of plague many of our friends and kin met disaster. Xu, Chen, Ying and Liu all died at once.”' } },

    { id: '218', y: 218, yr: '218', era: '建安二十三年',
      own: {},
      zh: { t: '许都之乱与汉中之争', x: '正月，太医令吉本与少府耿纪、司直韦晃在许都起兵，火烧丞相长史王必的军营，旋即被平定。刘备进军汉中，与夏侯渊、张郃在阳平关一带相持。曹操西征，九月抵达长安。' },
      en: { t: 'Revolt in Xu, war for Hanzhong', x: 'In the first month the imperial physician Ji Ben, with Geng Ji and Wei Huang, rises in Xu and burns the camp of the Chancellor’s chief clerk Wang Bi; the revolt is crushed at once. Liu Bei advances on Hanzhong and faces Xiahou Yuan and Zhang He around Yangping. Cao Cao marches west and reaches Chang’an in the ninth month.' },
      q: { s: '《武帝纪》', c: '古之葬者，必居瘠薄之地。其规西门豹祠西原上为寿陵，因高为基，不封不树。', en: '“In ancient times the dead were buried on poor land. Mark out my tomb on the plain west of the shrine of Ximen Bao. Use the high ground as its base; raise no mound and plant no trees.”' } },

    { id: '219', y: 219, yr: '219', era: '建安二十四年',
      own: { hanzhong: 'liubei', jingS: 'sun' },
      zh: { t: '定军山与樊城', x: '正月，夏侯渊在定军山被黄忠斩杀。曹操亲至汉中，五月撤军，刘备称汉中王。七月关羽北攻樊城，八月汉水暴涨，于禁七军被淹，于禁投降，庞德被斩，关羽“威震华夏”。孙权暗中与曹操联络，派吕蒙白衣渡江袭取江陵、公安，关羽腹背受敌，十二月在临沮被擒杀。' },
      en: { t: 'Dingjun Mountain and Fancheng', x: 'In the first month Xiahou Yuan is killed by Huang Zhong at Dingjun Mountain. Cao Cao comes to Hanzhong himself, withdraws in the fifth month, and Liu Bei proclaims himself King of Hanzhong. In the seventh month Guan Yu attacks Fancheng; in the eighth the Han River floods, Yu Jin’s seven armies are drowned, Yu Jin surrenders and Pang De is executed. Guan Yu’s “fame shakes the realm.” Then Sun Quan, secretly in touch with Cao Cao, sends Lü Meng with soldiers disguised as merchants to seize Jiangling and Gong’an. Caught between two enemies, Guan Yu is captured at Linju in the twelfth month and killed.' },
      q: { s: '《武帝纪》', c: '八月，汉水溢，灌禁军，军没，羽获禁，遂围仁。', en: 'In the eighth month the Han River overflowed and flooded Yu Jin’s army. It was lost; Guan Yu captured Yu Jin and laid siege to Cao Ren.' } },

    { id: '220', y: 220, yr: '220', era: '建安二十五年 / 黄初元年',
      own: {},
      nm: { cao: ['Wei', '魏'] },
      zh: { t: '曹操去世，汉朝终结', x: '正月，曹操在洛阳去世，曹丕继位为魏王。十月，曹丕逼汉献帝禅让，即皇帝位，改元黄初，国号魏，追尊曹操为武皇帝，庙号太祖。延续四百余年的汉朝至此终结，献帝被封为山阳公。' },
      en: { t: 'Cao Cao dies; the Han ends', x: 'In the first month Cao Cao dies at Luoyang and Cao Pi succeeds him as King of Wei. In the tenth month Cao Pi makes Emperor Xian abdicate, takes the throne as emperor of Wei, and posthumously names his father Emperor Wu, temple name Taizu. After more than four centuries the Han dynasty is over; the last emperor becomes Duke of Shanyang.' },
      q: { s: '《武帝纪》', c: '庚子，王崩于洛阳，年六十六。', en: 'On the gengzi day the king died at Luoyang, aged sixty-six.' } },

    { id: '221', y: 221, yr: '221–222', era: '黄初二至三年',
      own: {},
      nm: { liubei: ['Shu Han', '蜀汉'], sun: ['Wu', '吴'] },
      zh: { t: '刘备称帝与夷陵之战', x: '221年四月，刘备在成都称帝，国号汉，史称蜀汉。孙权向魏称臣，受封吴王。刘备东征孙权，出发前张飞被部将杀害。222年，吴将陆逊在夷陵（猇亭）火烧刘备连营七百里，蜀军大败。同年魏军三路伐吴，孙权与魏决裂。' },
      en: { t: 'A third emperor; Yiling', x: 'In the fourth month of 221 Liu Bei takes the title of emperor at Chengdu; his state calls itself Han, and history calls it Shu Han. Sun Quan declares himself Wei’s vassal and is made King of Wu. Liu Bei marches against him; Zhang Fei is murdered by his own officers before the campaign begins. In 222 the Wu general Lu Xun burns Liu Bei’s line of camps at Yiling and routs him. Wei then attacks Wu on three fronts, and Sun Quan breaks with Wei.' },
      q: { s: '《先主传》', c: '章武元年夏四月丙午，即皇帝位于成都武担之南。', en: 'On the bingwu day of the fourth month of the first year of Zhangwu he took the imperial throne south of Wudan hill at Chengdu.' } },

    { id: '223', y: 223, yr: '223', era: '章武三年 / 建兴元年',
      own: {},
      zh: { t: '白帝托孤', x: '刘备在白帝城病逝，太子刘禅即位，诸葛亮以丞相身份开府治事，总揽蜀汉军政。诸葛亮派邓芝出使东吴，恢复了吴蜀联盟。' },
      en: { t: 'The charge at Baidi', x: 'Liu Bei dies at Baidi. His son Liu Shan succeeds him, and Zhuge Liang, as Chancellor, takes charge of the whole state. He sends Deng Zhi to Wu and restores the alliance.' },
      q: { s: '《诸葛亮传》', c: '君才十倍曹丕，必能安国，终定大事。若嗣子可辅，辅之；如其不才，君可自取。', en: '“Your talent is ten times Cao Pi’s; you will surely secure the state and in the end achieve the great task. If my heir can be helped, help him. If he proves worthless, you may take the throne yourself.”' } },

    { id: '225', y: 225, yr: '225–228', era: '建兴三至六年',
      own: {},
      zh: { t: '南征与第一次北伐', x: '225年，诸葛亮亲征南中，平定叛乱。226年魏文帝曹丕去世，曹叡即位。227年诸葛亮上《出师表》，进驻汉中。228年春出祁山，陇右三郡响应，但马谡在街亭大败，北伐功亏一篑。同年秋，吴将陆逊在石亭大破魏军曹休。' },
      en: { t: 'The south, then the north', x: 'In 225 Zhuge Liang pacifies the rebellious south. In 226 Cao Pi dies and Cao Rui succeeds him. In 227 Zhuge Liang submits his memorial on taking the field and moves to Hanzhong. In spring 228 he marches out by Qishan and three commanderies in the west go over to him, but Ma Su is routed at Jieting and the campaign collapses. That autumn the Wu general Lu Xun crushes Cao Xiu of Wei at Shiting.' },
      q: { s: '诸葛亮《出师表》', c: '臣本布衣，躬耕于南阳，苟全性命于乱世，不求闻达于诸侯。', en: '“I was a commoner, farming in Nanyang, only trying to stay alive in a troubled age, with no wish to be known to the lords.”' } },

    { id: '229', y: 229, yr: '229', era: '黄龙元年（吴）',
      own: {},
      zh: { t: '孙权称帝', x: '孙权在武昌称帝，随后迁都建业。蜀汉朝中有人认为这是僭越，诸葛亮仍坚持遣使祝贺、维持联盟，两国约定灭魏之后中分天下。同年诸葛亮第三次北伐，攻取武都、阴平二郡。' },
      en: { t: 'Sun Quan takes the throne', x: 'Sun Quan proclaims himself emperor at Wuchang and moves his capital back to Jianye. Some in Shu call it usurpation, but Zhuge Liang insists on sending congratulations and keeping the alliance; the two states even agree how to divide Wei between them once it falls. Zhuge Liang’s third campaign takes the commanderies of Wudu and Yinping.' },
      q: { s: '《吴主传》', c: '夏四月，夏口、武昌并言黄龙、凤凰见。丙申，南郊即皇帝位。', en: 'In the fourth month Xiakou and Wuchang both reported sightings of a yellow dragon and a phoenix. On the bingshen day he took the imperial throne at the southern suburb altar.' } },

    { id: '234', y: 234, yr: '231–234', era: '建兴九至十二年',
      own: {},
      zh: { t: '五丈原', x: '231年诸葛亮再出祁山，用木牛运粮，射杀魏将张郃。234年他最后一次北伐，以流马运粮，在五丈原屯田，与司马懿对峙百余日。司马懿坚守不战，八月诸葛亮病逝军中，蜀军撤退。同年孙权配合出兵合肥新城，无功而返。' },
      en: { t: 'The Wuzhang Plains', x: 'In 231 Zhuge Liang marches out by Qishan again, moving grain on his “wooden oxen,” and kills the Wei general Zhang He. In 234 he makes his last campaign, with “gliding horses” for supply and soldiers farming on the Wuzhang Plains, and faces Sima Yi for over a hundred days. Sima Yi will not give battle. In the eighth month Zhuge Liang dies in camp and Shu withdraws. Sun Quan’s attack on the new fort at Hefei the same year also fails.' },
      q: { s: '《诸葛亮传》', c: '其年八月，亮疾病，卒于军，时年五十四。', en: 'In the eighth month of that year Zhuge Liang fell ill and died with the army, aged fifty-four (by the Chinese count).' } },

    { id: '238', y: 238, yr: '238–239', era: '景初二至三年',
      own: { liaodong: 'cao' },
      zh: { t: '平定辽东', x: '辽东的公孙渊自立为燕王，魏明帝曹叡派司马懿出征。司马懿围攻襄平，城破后大肆屠戮，辽东并入魏国。239年正月曹叡病逝，年仅八岁的曹芳即位，由曹爽与司马懿共同辅政。' },
      en: { t: 'Liaodong falls', x: 'Gongsun Yuan of Liaodong declares himself King of Yan, and Emperor Cao Rui sends Sima Yi against him. Sima Yi takes Xiangping and massacres many of its people, and Liaodong becomes part of Wei. Cao Rui dies in the first month of 239; the eight-year-old Cao Fang succeeds him with Cao Shuang and Sima Yi as joint regents.' } },

    { id: '249', y: 249, yr: '249', era: '正始十年 / 嘉平元年',
      own: {},
      zh: { t: '高平陵之变', x: '曹爽专权，排挤司马懿。正月，曹爽兄弟陪同曹芳出城拜谒明帝的高平陵，司马懿趁机关闭洛阳城门，控制禁军，奏免曹爽兄弟官职。曹爽交出兵权后，不久即以谋反罪与党羽一同被诛灭三族。魏国大权从此落入司马氏手中。' },
      en: { t: 'The Gaoping Tombs', x: 'Cao Shuang has been monopolising power and sidelining Sima Yi. In the first month, while Cao Shuang and his brothers are outside Luoyang escorting the young emperor to Cao Rui’s tomb at Gaoping, Sima Yi shuts the city gates, takes the palace guard and has them stripped of office. Cao Shuang gives up his command; soon after he and his allies are executed with their families on a charge of treason. Power in Wei now belongs to the Sima family.' },
      q: { s: '《三少帝纪》', c: '嘉平元年春正月甲午，车驾谒高平陵。太傅司马宣王奏免大将军曹爽、爽弟中领军羲、武卫将军训、散骑常侍彦官，以侯就第。', en: 'On the jiawu day of the first month of the first year of Jiaping the emperor visited the Gaoping tomb. The Grand Tutor Sima Yi memorialised that the Grand General Cao Shuang and his brothers Cao Xi, Cao Xun and Cao Yan be removed from office and sent home as marquises.' } },

    { id: '251', y: 251, yr: '251–252', era: '嘉平三至四年',
      own: {},
      zh: { t: '司马懿与孙权相继去世', x: '251年，太尉王凌在淮南谋废曹芳，司马懿亲自出兵，王凌自杀；同年八月司马懿去世，长子司马师继续掌权。252年，孙权在晚年储位之争（“二宫之争”）的阴影中去世，年幼的孙亮即位，诸葛恪辅政。' },
      en: { t: 'Sima Yi and Sun Quan die', x: 'In 251 Wang Ling plots in Huainan to depose the emperor; Sima Yi marches against him and Wang Ling kills himself. Sima Yi dies in the eighth month, and his eldest son Sima Shi takes over. In 252 Sun Quan dies in the shadow of the bitter succession quarrel between two of his sons; the young Sun Liang succeeds him with Zhuge Ke as regent.' } },

    { id: '263', y: 263, yr: '263', era: '景元四年',
      own: { liang: 'cao', hanzhong: 'cao', yi: 'cao' },
      zh: { t: '蜀汉灭亡', x: '掌权的司马昭派钟会、邓艾、诸葛绪三路伐蜀。姜维在剑阁挡住钟会，邓艾却从阴平小道翻山越岭直取江油、绵竹，诸葛亮之子诸葛瞻、孙子诸葛尚战死。刘禅开成都投降，蜀汉灭亡，立国四十三年。' },
      en: { t: 'The fall of Shu', x: 'Sima Zhao, now ruling Wei, sends Zhong Hui, Deng Ai and Zhuge Xu against Shu. Jiang Wei holds Zhong Hui at Jiange, but Deng Ai crosses the mountains by the Yinping path and strikes at Jiangyou and Mianzhu, where Zhuge Liang’s son Zhuge Zhan and grandson Zhuge Shang die fighting. Liu Shan surrenders Chengdu. Shu Han has lasted 43 years.' } },

    { id: '265', y: 265, yr: '265–266', era: '咸熙二年 / 泰始元年',
      own: { liang: 'jin', bing: 'jin', sili: 'jin', ji: 'jin', you: 'jin', liaodong: 'jin', qing: 'jin', yan: 'jin', xu: 'jin', yu: 'jin', huainan: 'jin', jingN: 'jin', hanzhong: 'jin', yi: 'jin' },
      zh: { t: '晋代魏', x: '司马昭去世，其子司马炎继任晋王。同年十二月（公历已是266年初），司马炎逼魏元帝曹奂禅让，建立晋朝，是为晋武帝。曹魏立国四十六年而亡，正如四十五年前曹丕代汉。' },
      en: { t: 'Jin replaces Wei', x: 'Sima Zhao dies and his son Sima Yan succeeds him as King of Jin. In the twelfth month (early 266 by the Western calendar) Sima Yan makes the last Wei emperor, Cao Huan, abdicate and founds the Jin dynasty. Wei falls after 46 years, the same way Cao Pi took the throne from the Han.' } },

    { id: '280', y: 280, yr: '280', era: '太康元年',
      own: { jingS: 'jin', jiangdong: 'jin', jiao: 'jin' },
      zh: { t: '三国归晋', x: '晋军六路伐吴，王濬率楼船从益州顺江而下，直抵建业。吴主孙皓投降，东吴灭亡。自184年黄巾起义算起近百年的分裂与战乱结束，但晋朝的统一不到二十年就在“八王之乱”中瓦解。' },
      en: { t: 'All under Jin', x: 'Jin attacks Wu on six fronts; Wang Jun brings a fleet of tower ships down the Yangtze from Yi to Jianye. Sun Hao, the last ruler of Wu, surrenders. Almost a century of division and war since the Yellow Turbans is over, though Jin’s unity will fall apart within twenty years in the War of the Eight Princes.' },
      q: { s: '《武帝纪》评', c: '太祖运筹演谋，鞭挞宇内，揽申、商之法术，该韩、白之奇策……抑可谓非常之人，超世之杰矣。', en: 'Chen Shou’s verdict on Cao Cao: “He planned and schemed and whipped the realm into shape, gathering the methods of the Legalists and the stratagems of the great generals… He can truly be called an extraordinary man, a hero beyond his age.”' } }
  ],

  /* The six lives. Each entry is keyed by step id: [place, Chinese, English] or [place, Chinese, English, 1] in the
     year they die. Legacy entries after death have no place. Years with no entry show the last known place and say
     the record is silent. */
  people: {
    caocao: {
      n: ['Cao Cao', '曹操'], zh: '曹操', ch: ['曹', '曹'], born: 155, died: 220, fac: 'cao',
      life: {
        '155': ['qiao', '生于沛国谯县。', 'Born in Qiao county, Pei.'],
        '174': ['luoyang', '少年时“任侠放荡，不治行业”，只有桥玄、何颙看重他。桥玄对他说：“天下将乱，非命世之才不能济也，能安之者，其在君乎！”他任洛阳北部尉时造五色大棒悬于县门，犯禁者不避豪强一律杖杀，连宠宦蹇硕的叔父夜行也被打死（裴注引《曹瞒传》）。', 'As a youth he was “chivalrous and wild, with no fixed occupation”; only Qiao Xuan and He Yong thought much of him. Qiao Xuan told him: “The world is about to fall into chaos; only a man of genius can save it, and the one to bring peace may be you.” As commandant in Luoyang he hung coloured staves at his gate and beat to death anyone breaking the curfew, however powerful, including an uncle of the favourite eunuch Jian Shuo (Pei’s notes, quoting the Cao Man Zhuan).'],
        '184': ['yingchuan', '任骑都尉，随皇甫嵩、朱儁讨伐颍川黄巾。随后迁济南相：国中十余县的长吏多依附权贵、贪赃枉法，他奏免了其中八人，又禁断淫祀，“奸宄逃窜，郡界肃然”。', 'As Chief Commandant of Cavalry he fights the Yellow Turbans in Yingchuan under Huangfu Song and Zhu Jun. Made chancellor of Jinan, he finds most of the heads of its ten-odd counties corrupt hangers-on of the powerful, has eight of them dismissed, and bans unofficial cults; “the wicked fled and the commandery was orderly.”'],
        '187': ['qiao', '被任命为东郡太守，他称病不就，回到谯县，在城外筑精舍，“秋夏读书，冬春射猎”（裴注引《魏武故事》所载曹操自述）。他拒绝参与王芬废立皇帝的密谋。188年被任命为西园八校尉之一的典军校尉。', 'Offered the post of Administrator of Dong, he pleads illness and goes home to Qiao, where he builds a retreat outside the city, “reading in summer and autumn, hunting in winter and spring” (his own later account, quoted by Pei). He refuses to join Wang Fen’s plot to depose the emperor. In 188 he is made one of the eight Colonels of the Western Garden.'],
        '189': ['chenliu', '他拒绝董卓的拉拢，改名换姓抄小路东逃；过中牟时被亭长怀疑扣押，幸有人认出他、代为求情才获释。在成皋吕伯奢家杀人一事，裴注引了三种说法，出入很大，其中孙盛《杂记》记他说：“宁我负人，毋人负我。”到陈留后，他散尽家财，招募义兵，十二月在己吾起兵。', 'He turns down Dong Zhuo, changes his name and escapes east by back roads; at Zhongmou a local officer arrests him on suspicion, and he is freed only because someone recognises him and pleads for him. Pei gives three very different versions of how he killed members of Lü Boshe’s household on the way; one, from Sun Sheng, has him say: “Better that I betray others than that others betray me.” At Chenliu he spends his family fortune raising troops, and in the twelfth month takes the field at Jiwu.'],
        '190': ['xingyang', '以行奋武将军身份加入关东联军。诸军屯驻酸枣，日日置酒高会，无人敢先进，只有他引兵西进，在荥阳汴水大败。他回到酸枣责备诸将，无人响应，于是与夏侯惇等前往扬州募兵。袁绍、韩馥打算拥立刘虞为帝，他也拒绝了。', 'He joins the coalition as acting General of Vigorous Might. The armies at Suanzao feast every day and none will advance; he alone marches west and is beaten at the Bian River. Back at Suanzao he berates the lords, to no effect, and goes south with Xiahou Dun to recruit in Yang province. When Yuan Shao and Han Fu propose to make Liu Yu emperor, he refuses.'],
        '191': ['puyang', '黑山军于毒、白绕等攻打东郡，他在濮阳击破白绕，被袁绍表为东郡太守，治东武阳。这是他的第一块根据地。', 'When the Black Mountain bandits attack Dong commandery he beats Bai Rao at Puyang and is made Administrator of Dong, his first base.'],
        '192': ['shouzhang', '济北相鲍信等人迎他领兖州牧。他在寿张以东与黄巾苦战，鲍信力战而死，曹操悬赏寻找其尸体未得，以木刻其形而哭祭。他追击黄巾至济北，受降卒三十余万，收编为“青州兵”。', 'Bao Xin and others invite him to take charge of Yan. Fighting the Yellow Turbans east of Shouzhang, Bao Xin is killed; Cao Cao offers a reward for his body, cannot find it, and mourns over a wooden image of him. He follows the rebels to Jibei and takes the surrender of 300,000 soldiers, the core of the Qingzhou army.'],
        '193': ['pengcheng', '在匡亭大破袁术，追至九江。秋天以父仇为名东征陶谦，攻下十余城。范晔《后汉书·陶谦传》说此役“凡杀男女数十万人，鸡犬无余，泗水为之不流”。', 'He routs Yuan Shu at Kuangting and chases him to Jiujiang. In autumn, to avenge his father, he attacks Tao Qian and takes more than ten cities. Fan Ye’s Book of the Later Han says he killed hundreds of thousands, “not a dog or chicken left, and the Si River choked with bodies.”'],
        '194': ['puyang', '夏天再征徐州，“所过多所残戮”。张邈、陈宫迎吕布入兖州，只剩荀彧、程昱守住的鄄城和范、东阿二县。他回师与吕布在濮阳相持百余日：一次夜战中青州兵被冲散，他冲出火海时坠马，烧伤左手掌，靠司马楼异扶他上马才得以脱身。蝗灾饥荒之下，双方各自罢兵。', 'In summer he invades Xu again, “with much slaughter wherever he passed.” Zhang Miao and Chen Gong bring Lü Bu into Yan; only Juancheng, held by Xun Yu and Cheng Yu, and two other counties stay loyal. He faces Lü Bu at Puyang for over a hundred days. In one night battle his Qingzhou troops break; riding out through the flames he falls from his horse and burns his left palm, and the officer Lou Yi helps him back into the saddle. Locusts and famine end the fighting.'],
        '195': ['yongqiu', '在定陶、巨野接连击败吕布。八月围攻张邈之弟张超于雍丘，十二月城破，张超自杀，张邈被部下所杀，他诛灭张邈三族。十月被正式任命为兖州牧。', 'He beats Lü Bu at Dingtao and Juye. In the eighth month he besieges Zhang Miao’s brother Zhang Chao at Yongqiu; it falls in the twelfth, Zhang Chao kills himself, Zhang Miao is killed by his own men, and Cao Cao exterminates Zhang Miao’s family. In the tenth month he is formally appointed Governor of Yan.'],
        '196': ['xu', '迎天子一事诸将多有疑虑，荀彧、程昱力劝。他入洛护驾，被授予节钺、录尚书事，九月迁都许县，任大将军、封武平侯。袁绍以位在其下为耻，他把大将军让给袁绍，自任司空、行车骑将军。刘备被吕布夺去徐州后来投，他以刘备为豫州牧。', 'Many of his officers doubt the wisdom of taking in the emperor; Xun Yu and Cheng Yu persuade him. He goes to Luoyang, is given the insignia of command and control of the secretariat, and in the ninth month moves the court to Xu as Grand General and Marquis of Wuping. When Yuan Shao is offended at ranking below him, he yields the title to Yuan Shao and becomes Minister of Works. He takes in Liu Bei, driven out of Xu by Lü Bu.'],
        '197': ['wan', '正月到宛，张绣投降。《张绣传》说他纳了张绣叔父张济的遗孀，张绣怀恨，又听说曹操要除掉自己，于是突袭曹营。曹操中流矢，长子曹昂、侄子曹安民和大将典韦战死。九月他东征称帝的袁术，袁术弃军渡淮而逃。', 'At Wan Zhang Xiu surrenders. According to Zhang Xiu’s biography, Cao Cao took the widow of Zhang Xiu’s uncle Zhang Ji as a concubine; Zhang Xiu, resentful and hearing that Cao Cao meant to have him killed, attacks the camp. Cao Cao is hit by an arrow; his eldest son Cao Ang, his nephew Cao Anmin and his bodyguard Dian Wei are killed. In the ninth month he marches on the self-proclaimed emperor Yuan Shu, who abandons his army and flees across the Huai.'],
        '198': ['xiapi', '正月设立军师祭酒，郭嘉任之。三月围张绣于穰城，撤退时在安众设奇兵大破追兵。九月东征吕布，围下邳，引沂、泗二水灌城。吕布被擒后请求效力，曹操面有犹豫，刘备说：“明公不见布之事丁建阳及董太师乎！”曹操遂下令缢杀吕布（《吕布传》）。', 'He creates the post of Libationer of the Army for Guo Jia. In the third month he besieges Zhang Xiu at Rang and, withdrawing, ambushes the pursuers at Anzhong. In the ninth he marches on Lü Bu and floods Xiapi. When Lü Bu, captured, offers to serve him, Cao Cao hesitates; Liu Bei says, “Have you forgotten how he served Ding Yuan and Dong Zhuo?” and Cao Cao has him strangled (Biography of Lü Bu).'],
        '199': ['guandu', '他派刘备截击袁术，随即后悔。十一月，张绣听从贾诩的建议率众来降，他不计杀子之仇，封张绣为列侯。十二月进驻官渡。', 'He sends Liu Bei to intercept Yuan Shu and regrets it at once. In the eleventh month Zhang Xiu, on Jia Xu’s advice, comes over to him; Cao Cao ignores the death of his son and makes Zhang Xiu a marquis. In the twelfth month he moves to Guandu.'],
        '200': ['guandu', '他不顾袁绍在背后威胁，亲率大军东征刘备。四月用荀攸声东击西之计解白马之围，关羽斩颜良；又在延津以辎重为饵，斩文丑。官渡相持中他兵少粮缺，写信给荀彧想退回许县，荀彧回信劝他坚持。十月许攸来投，献计袭乌巢，他亲率步骑五千夜袭，烧尽袁军粮草，斩淳于琼，张郃、高览来降。', 'Ignoring the threat from Yuan Shao, he marches east against Liu Bei himself. In the fourth month he relieves Baima with Xun You’s feint, where Guan Yu kills Yan Liang, and kills Wen Chou at Yanjin after baiting him with the baggage train. At Guandu, short of men and food, he writes to Xun Yu proposing to fall back on Xu; Xun Yu tells him to hold. In the tenth month Xu You defects and tells him about Wuchao. He leads 5,000 men there by night, burns all the grain, kills Chunyu Qiong, and Zhang He and Gao Lan come over to him.'],
        '201': ['cangting', '四月在仓亭再败袁绍。九月南征汝南的刘备，刘备逃往荆州。', 'In the fourth month he beats Yuan Shao again at Cangting. In the ninth he marches against Liu Bei in Runan, who flees to Jing.'],
        '202': ['qiao', '正月回到故乡谯县，见“旧土人民，死丧略尽”，下令为无后的阵亡将士寻立继嗣，授田、给耕牛、设学校教育其子弟。五月袁绍去世，九月他北上进攻袁谭、袁尚。', 'In the first month he returns to Qiao and finds the people of his home district almost all dead. He orders heirs to be found for soldiers who died without children, and gives them land, oxen and schools. Yuan Shao dies in the fifth month; in the ninth he marches north against Yuan Tan and Yuan Shang.'],
        '203': ['liyang', '三月攻破黎阳，五月回许。七月下令各郡国修文学、设校官。八月听从郭嘉之计，佯攻刘表，坐等二袁内讧；袁谭兵败求援，他回师北上。', 'He takes Liyang in the third month and returns to Xu in the fifth. In the seventh he orders schools set up in every commandery. In the eighth, on Guo Jia’s advice, he feints south against Liu Biao while the Yuan brothers fight; when the beaten Yuan Tan asks for help, he turns north.'],
        '204': ['ye', '攻下邺城后，他亲往袁绍墓前祭奠，痛哭流涕，抚慰袁绍的妻子，归还其家人财物。九月下令河北免除当年租赋，并严惩豪强兼并。献帝任命他兼领冀州牧，他辞去兖州牧，从此以邺城为根据地。', 'After Ye falls he goes to Yuan Shao’s tomb and weeps, comforts Yuan Shao’s widow and returns her family’s treasures. In the ninth month he excuses the north from that year’s taxes and cracks down on landlords swallowing up land. Made governor of Ji, he gives up Yan; Ye is now his capital.'],
        '205': ['nanpi', '正月在南皮斩袁谭。他下令与袁氏同恶者一律既往不咎，禁止私自复仇和厚葬。', 'He kills Yuan Tan at Nanpi in the first month, pardons all who had sided with the Yuan, and bans private vendettas and lavish burials.'],
        '206': ['huguan', '亲征高干，三月围攻壶关，壶关投降，并州平定。八月东征海贼管承。', 'He marches against Gao Gan and besieges Huguan, which surrenders in the third month. In the eighth he campaigns against the pirate Guan Cheng on the coast.'],
        '207': ['bailang', '二月大封功臣二十余人为列侯。七月大雨，沿海道路不通，他采纳田畴的建议改走卢龙塞，“堑山堙谷五百余里”。八月在白狼山大破乌桓。归途中，最倚重的谋士郭嘉病逝，年三十八，曹操十分悲痛。', 'In the second month he makes over twenty of his followers marquises. In the seventh, with the coast road flooded, he takes Tian Chou’s advice and goes through Lulong Pass, “cutting through mountains and filling valleys for over five hundred li.” In the eighth he routs the Wuhuan at White Wolf Mountain. On the way back Guo Jia, the adviser he relied on most, dies aged 38; Cao Cao is grief-stricken.'],
        '208': ['chibi', '正月在邺城开凿玄武池操练水军。六月出任丞相。南征时他率五千轻骑一日一夜行三百余里，在当阳长坂追上并击溃刘备（《先主传》）。进占江陵后致书孙权：“今治水军八十万众，方与将军会猎于吴。”（裴注引《江表传》）十二月在赤壁失利，又遇大疫，引军北还。', 'In the first month he digs the Xuanwu Pool at Ye to train sailors. In the sixth he becomes Chancellor. Marching south, he takes 5,000 light cavalry three hundred li in a day and a night to catch and rout Liu Bei at Changban (Biography of Liu Bei). From Jiangling he writes to Sun Quan: “I now have a navy of 800,000, and will meet you for a hunt in Wu” (Pei, quoting the Jiangbiao Zhuan). In the twelfth month he is beaten at Red Cliffs, plague breaks out, and he leads the army north.'],
        '209': ['hefei', '在谯县造轻舟、练水军，七月进驻合肥。他下令为阵亡将士家属发放抚恤，在扬州设置郡县长吏，开芍陂屯田。', 'He builds light boats and trains a navy at Qiao, and in the seventh month moves to Hefei. He orders relief for the families of the dead, appoints officials across Yang province, and starts farm colonies at Quebei.'],
        '210': ['ye', '春天下《求贤令》，主张“唯才是举”。冬天修建铜雀台。十二月下《让县自明本志令》（见裴注引《魏武故事》），回顾自己的一生，说：“设使国家无有孤，不知当几人称帝，几人称王。”他让还阳夏、柘、苦三县封地，但明确拒绝交出兵权。', 'In spring he issues his edict seeking talent: “talent is the only test.” In winter he builds the Bronze Bird Terrace. In the twelfth month he issues an edict reviewing his life (quoted by Pei): “Had there been no me, who knows how many would have called themselves emperor, how many king?” He gives back three of his four fief counties but refuses outright to give up his army.'],
        '211': ['tongguan', '潼关北渡黄河时，马超率万余步骑突袭，校尉丁斐放出牛马引敌兵争抢，他才得以渡河（《许褚传》记许褚扶他上船，举马鞍为他遮挡箭矢）。他采纳贾诩“离之而已”的计策，阵前与韩遂叙旧，又送去涂改过的书信，使马超疑心韩遂，然后决战大胜。十月北征杨秋，十二月留夏侯渊屯长安。', 'Crossing the Yellow River north of Tong Pass, he is attacked by Ma Chao with over ten thousand men; the colonel Ding Fei lets loose cattle and horses, the enemy scramble for them, and he gets across (Xu Chu’s biography says Xu Chu got him onto a boat and shielded him from arrows with a saddle). Using Jia Xu’s plan to “divide them,” he chats with Han Sui in front of the armies and then sends him a letter full of erasures, so that Ma Chao suspects Han Sui, and then wins the decisive battle. He leaves Xiahou Yuan in charge of Chang’an.'],
        '212': ['qiao', '正月回邺，被准许“赞拜不名，入朝不趋，剑履上殿，如萧何故事”。荀彧反对为他晋爵魏公，“太祖由是心不能平”。十月东征孙权时，他上表请荀彧到谯县劳军，随即把荀彧留在军中。荀彧病留寿春去世，陈寿说是“以忧薨”，裴注引《魏氏春秋》说是收到空食盒后服毒自尽。', 'Back at Ye in the first month, he is granted the honours of Xiao He: announced without his name, no need to hurry at court, sword and shoes in the hall. Xun Yu opposes making him Duke of Wei, and “from then on Cao Cao was uneasy with him.” Marching against Sun Quan in the tenth month, he asks for Xun Yu to come to Qiao to reward the troops, then keeps him with the army. Xun Yu falls ill at Shouchun and dies: of worry, says Chen Shou; of poison, after receiving an empty food box, says a source quoted by Pei.'],
        '213': ['ruxu', '正月进攻濡须口，攻破孙权的江西营寨。裴注引《吴历》，他见孙权舟船器仗军伍整肃，叹道：“生子当如孙仲谋，刘景升儿子若豚犬耳！”五月受封魏公，加九锡。', 'In the first month he attacks Ruxu and takes Sun Quan’s camp on the north bank. According to a source quoted by Pei, seeing the order of Sun Quan’s fleet and troops he sighs: “If you have a son, he should be like Sun Zhongmou; Liu Biao’s sons were pigs and dogs.” In the fifth month he is made Duke of Wei with the Nine Bestowments.'],
        '214': ['hefei', '正月始耕籍田。七月东征孙权，无功而还。十一月伏皇后事发，皇后被废而死。', 'In the first month he performs the ritual ploughing. He marches against Sun Quan in the seventh month without result. In the eleventh Empress Fu is exposed, deposed and dies.'],
        '215': ['nanzheng', '三月西征张鲁，七月攻破阳平关，进入南郑。刘晔等人劝他乘胜取蜀，他没有采纳（《刘晔传》）。十一月张鲁来降，他封张鲁及五子为列侯。十二月留夏侯渊镇守汉中，回军。', 'He marches west in the third month, breaks through Yangping Pass in the seventh and enters Nanzheng. Liu Ye and others urge him to press on into Shu; he declines (Biography of Liu Ye). Zhang Lu surrenders in the eleventh month and he and his five sons are made marquises. He leaves Xiahou Yuan to hold Hanzhong.'],
        '216': ['ye', '五月进爵魏王。崔琰被赐死，为崔琰鸣不平的毛玠也被罢官（《崔琰传》《毛玠传》）。十月再征孙权。', 'He becomes King of Wei in the fifth month. Cui Yan is ordered to kill himself, and Mao Jie, who protests, is dismissed (Biographies of Cui Yan and Mao Jie). In the tenth month he marches on Sun Quan again.'],
        '217': ['ruxu', '二月进攻濡须，孙权请降，双方重修婚约。四月获准设天子旌旗，出入称警跸；十月冕十二旒、乘金根车，立曹丕为魏太子。', 'In the second month he attacks Ruxu and Sun Quan offers submission; the two renew a marriage pact. In the fourth month he is allowed the emperor’s banners, and in the tenth the emperor’s crown and carriage; he names Cao Pi Crown Prince.'],
        '218': ['changan', '六月下令预作寿陵，要求“因高为基，不封不树”。七月西征刘备，九月抵达长安。', 'In the sixth month he orders his tomb prepared: “use the high ground as its base; raise no mound and plant no trees.” In the seventh he marches west against Liu Bei, reaching Chang’an in the ninth.'],
        '219': ['mopi', '三月出斜谷至阳平，刘备据险坚守，五月撤军（“鸡肋”之叹见裴注引《九州春秋》）。主簿杨修被杀，《陈思王植传》说是因为杨修有才谋、又是袁术的外甥。他派徐晃救樊城，自己进驻摩陂。孙权上书请求讨伐关羽，并劝他称帝，他说：“是儿欲踞吾著炉火上邪！”（裴注引《魏略》）', 'In the third month he comes through the Xie valley to Yangping, but Liu Bei holds the heights and he withdraws in the fifth (the “chicken rib” remark is from a source quoted by Pei). His secretary Yang Xiu is executed; Cao Zhi’s biography says it was because Yang Xiu was clever and a nephew of Yuan Shu. He sends Xu Huang to relieve Fancheng and camps at Mopi. When Sun Quan writes offering to attack Guan Yu and urging him to take the throne, he says: “This boy wants to sit me on a stove!” (Pei, quoting the Weilüe).'],
        '220': ['luoyang', '正月回到洛阳，孙权送来关羽的首级。庚子日（公历220年3月15日）他在洛阳去世，年六十六。遗令说：“天下尚未安定，未得遵古也。葬毕，皆除服。……敛以时服，无藏金玉珍宝。”二月葬于高陵，谥号武王，十月被曹丕追尊为武皇帝。', 'In the first month he returns to Luoyang, and Sun Quan sends him Guan Yu’s head. On the gengzi day (15 March 220) he dies at Luoyang, aged 66 by the Chinese count. His last orders: “The realm is not yet at peace; the old customs cannot be followed. When the burial is over, put off mourning… dress me in everyday clothes, and bury no gold, jade or treasure with me.” He is buried at the Gao tomb in the second month; in the tenth Cao Pi names him Emperor Wu.', 1],
        '221': [null, '曹丕建立的魏国稳据北方，并接受孙权称臣。', 'The Wei his son founded holds the north and accepts Sun Quan’s submission.'],
        '234': [null, '魏国挡住了诸葛亮的全部北伐。', 'Wei has stopped every one of Zhuge Liang’s campaigns.'],
        '249': [null, '他亲自征辟的司马懿，从曹氏手中夺走了权力。', 'Sima Yi, a man he himself recruited, takes power from the Cao family.'],
        '265': [null, '司马炎终结魏国。曹魏自曹丕称帝起延续了四十六年。', 'Sima Yan ends Wei, 46 years after Cao Pi took the throne.'],
        '280': [null, '他开启、却在赤壁功亏一篑的统一，由晋完成。后世说书人把他写成奸雄，陈寿则称他“非常之人，超世之杰”。', 'Jin finishes the unification he began and lost at Red Cliffs. Storytellers later made him a villain; Chen Shou called him “an extraordinary man, a hero beyond his age.”']
      }
    },
    liubei: {
      n: ['Liu Bei', '刘备'], zh: '劉備', ch: ['劉', '刘'], born: 161, died: 223, fac: 'liubei',
      life: {
        '174': ['zhuo', '涿郡涿县人，汉景帝之子中山靖王刘胜之后。少年丧父，与母亲以贩履织席为业。十五岁时与公孙瓒一同师事卢植。', 'From Zhuo, a descendant of Liu Sheng, Prince Jing of Zhongshan, son of Emperor Jing of Han. His father died young, and he and his mother lived by selling sandals and weaving mats. At fifteen he studied under Lu Zhi alongside Gongsun Zan.'],
        '184': ['zhuo', '得中山大商张世平、苏双资助，与关羽、张飞组织乡勇讨伐黄巾，因功任安喜县尉。督邮来县办事，他求见不得，直入将督邮捆绑，杖打二百，解下官印挂在督邮脖子上，弃官而去。', 'Funded by the horse traders Zhang Shiping and Su Shuang, he raises a band with Guan Yu and Zhang Fei against the Yellow Turbans and is made commandant of Anxi county. When an inspector refuses to see him, he ties the man up, gives him two hundred strokes, hangs his seal of office round the inspector’s neck and leaves.'],
        '187': ['gaotang', '先后任下密丞、高唐尉，升任高唐令。', 'He serves as assistant magistrate of Xiami, then commandant and magistrate of Gaotang.'],
        '191': ['pingyuan', '高唐被盗贼攻破，他投奔同窗公孙瓒，因功任平原相。', 'When bandits take Gaotang he joins his old schoolmate Gongsun Zan and becomes chancellor of Pingyuan.'],
        '193': ['pei', '曹操攻徐州，他与田楷援救陶谦，陶谦表他为豫州刺史，屯驻小沛。', 'When Cao Cao attacks Xu he comes with Tian Kai to help Tao Qian, who makes him inspector of Yu and stations him at Xiaopei.'],
        '194': ['xiapi', '陶谦病重，临终嘱托“非刘备不能安此州”。他一再推辞，在陈登、孔融劝说下接管徐州。', 'Dying, Tao Qian says that only Liu Bei can hold the province. After refusing several times, he takes over Xu on the urging of Chen Deng and Kong Rong.'],
        '196': ['xu', '他与袁术在盱眙、淮阴相持，吕布趁机袭取下邳，俘获其妻子。他被迫向吕布求和，后又被吕布击败，投奔曹操。', 'While he holds off Yuan Shu at Xuyi and Huaiyin, Lü Bu seizes Xiapi and his wife and children. Forced to make peace and then beaten again, he goes over to Cao Cao.'],
        '198': ['xiapi', '随曹操东征吕布。吕布被擒后请求效力，他提醒曹操想想丁原、董卓的下场。', 'He marches with Cao Cao against Lü Bu, and when Lü Bu begs to serve Cao Cao, reminds him what happened to Ding Yuan and Dong Zhuo.'],
        '199': ['xiapi', '曹操从容对他说：“今天下英雄，唯使君与操耳。”他正在吃饭，惊得筷子掉在地上（《先主传》）。他与董承秘密接受“衣带诏”，谋诛曹操。奉命截击袁术后，他在下邳杀车胄，据徐州反曹。', 'Cao Cao tells him calmly: “The only heroes in the world are you and I.” He drops his chopsticks (Biography of Liu Bei). He secretly joins Dong Cheng’s plot under the “girdle edict.” Sent to stop Yuan Shu, he kills Che Zhou at Xiapi and holds Xu against Cao Cao.'],
        '200': ['runan', '曹操亲征，他大败，弃妻子投奔袁绍；后被派往汝南联络黄巾刘辟等。', 'Cao Cao marches on him in person; beaten, he abandons his family and flees to Yuan Shao, who later sends him to rouse the Yellow Turban leader Liu Pi in Runan.'],
        '201': ['xinye', '曹操南征，他投奔荆州刘表，屯驻新野。', 'With Cao Cao coming south, he flees to Liu Biao in Jing and is stationed at Xinye.'],
        '207': ['xinye', '他三次前往隆中拜访诸葛亮才得相见，“由是与亮情好日密”。关羽、张飞不悦，他说：“孤之有孔明，犹鱼之有水也。”', 'Only on his third visit to Longzhong does he see Zhuge Liang, and they grow close. When Guan Yu and Zhang Fei grumble, he says: “Having Kongming is like a fish having water.”'],
        '208': ['changban', '曹操大军南下，刘琮投降，他率十余万百姓南撤，日行十余里，在当阳长坂被曹操追上击溃，弃妻子逃走，赵云保护幼子刘禅，张飞据水断桥。他退到夏口，派诸葛亮联吴，与孙权共同在赤壁击败曹操。', 'Liu Cong surrenders; he retreats south with over a hundred thousand civilians, covering barely ten li a day, and is caught and routed at Changban. He flees, leaving his family; Zhao Yun saves his son Liu Shan, and Zhang Fei holds the bridge. Falling back to Xiakou, he sends Zhuge Liang to Sun Quan and together they beat Cao Cao at Red Cliffs.'],
        '209': ['gongan', '表刘琦为荆州刺史，南征四郡。刘琦病死后，众人推他为荆州牧，治公安。孙权把妹妹嫁给他。', 'He names Liu Qi inspector of Jing and takes the four southern commanderies. When Liu Qi dies he is acclaimed governor of Jing, at Gong’an. Sun Quan gives him his sister in marriage.'],
        '210': ['gongan', '他亲往京口见孙权，请求“都督荆州”。周瑜上疏建议软禁刘备，孙权没有采纳。', 'He goes to Sun Quan at Jingkou to ask for command of Jing. Zhou Yu urges Sun Quan to keep him there as a hostage; Sun Quan declines.'],
        '211': ['fu', '刘璋派法正迎他入蜀抵御张鲁，他留诸葛亮、关羽守荆州，率数万人入益州，刘璋亲到涪城相迎，欢宴百余日。', 'Liu Zhang sends Fa Zheng to invite him into Yi against Zhang Lu. Leaving Zhuge Liang and Guan Yu to hold Jing, he goes in with tens of thousands of men; Liu Zhang meets him at Fu and they feast for over a hundred days.'],
        '212': ['jiameng', '他驻扎葭萌一年，广树恩德收买人心。年底借口回援荆州向刘璋要兵要粮，被拒后斩杀刘璋部将杨怀、高沛，回军南攻成都。', 'For a year at Jiameng he builds goodwill. At the end of 212 he asks Liu Zhang for troops and supplies, ostensibly to help Jing; refused, he kills Liu Zhang’s officers Yang Huai and Gao Pei and turns south against Chengdu.'],
        '213': ['luo', '围攻雒城近一年，谋士庞统中流矢身亡，年三十六。', 'He besieges Luo for nearly a year; his adviser Pang Tong is killed by an arrow, aged 36.'],
        '214': ['chengdu', '夏天攻下雒城，与诸葛亮、张飞、赵云会师围成都。马超来投，城中震恐，刘璋出降。他自领益州牧。', 'He takes Luo in summer and, joined by Zhuge Liang, Zhang Fei and Zhao Yun, surrounds Chengdu. Ma Chao comes over to him, the city panics, and Liu Zhang surrenders. He becomes governor of Yi.'],
        '215': ['gongan', '孙权索还荆州，派吕蒙夺取长沙等三郡。他率五万人东下公安，听说曹操取了汉中，才与孙权以湘水为界讲和。', 'Sun Quan demands Jing back and sends Lü Meng to seize three commanderies. He comes down to Gong’an with 50,000 men, but on hearing that Cao Cao has taken Hanzhong, makes peace and divides Jing along the Xiang River.'],
        '218': ['yangping', '进兵汉中，与夏侯渊、张郃在阳平关相持。', 'He advances into Hanzhong and faces Xiahou Yuan and Zhang He at Yangping.'],
        '219': ['hanzhong', '正月黄忠在定军山斩杀夏侯渊；曹操亲来争夺，刘备据险不战，曹操退兵。七月他在沔阳自称汉中王。年底关羽兵败身死，荆州尽失。', 'In the first month Huang Zhong kills Xiahou Yuan at Dingjun Mountain; Cao Cao comes in person, Liu Bei holds the heights and refuses battle, and Cao Cao leaves. In the seventh month he proclaims himself King of Hanzhong at Mianyang. At the year’s end Guan Yu is killed and Jing is lost.'],
        '220': ['chengdu', '传闻汉献帝已被曹丕所害，他为献帝发丧，追谥孝愍皇帝。', 'Hearing a false rumour that Emperor Xian has been murdered, he holds mourning for him.'],
        '221': ['yiling', '四月在成都称帝。七月东征孙权，出征前张飞被部将杀害。222年他在夷陵与陆逊相持半年，被火攻大败，退回白帝城。', 'He takes the throne at Chengdu in the fourth month and marches against Wu in the seventh; Zhang Fei is murdered just before. In 222 he faces Lu Xun at Yiling for half a year, is burned out of his camps, and retreats to Baidi.'],
        '223': ['baidi', '四月病逝于白帝城永安宫，年六十三（虚岁）。临终托孤于诸葛亮，又留遗诏告诫刘禅：“勿以恶小而为之，勿以善小而不为。”（裴注引《诸葛亮集》）', 'He dies at Baidi in the fourth month. He entrusts his son to Zhuge Liang, and leaves him a last edict: “Do not do evil because it is small; do not neglect good because it is small” (quoted by Pei from Zhuge Liang’s collected works).', 1],
        '225': [null, '诸葛亮辅佐刘禅，平定南中，准备北伐。', 'Zhuge Liang governs for his son, pacifies the south and prepares to march north.'],
        '263': [null, '刘禅向邓艾投降，后在洛阳受封安乐公。刘备建立的蜀汉延续了四十三年。', 'Liu Shan surrenders to Deng Ai and lives out his life in Luoyang as Duke of Anle. The state Liu Bei founded has lasted 43 years.'],
        '280': [null, '一千多年后，《三国演义》把他塑造成仁德的汉室正统；陈寿则评价他“弘毅宽厚，知人待士”，但“机权干略，不逮魏武”。', 'A thousand years later the novel made him the virtuous heir of Han. Chen Shou judged him “broad-minded and generous, a good judge of men,” but “in strategy and resource not the equal of Cao Cao.”']
      }
    },
    sunquan: {
      n: ['Sun Quan', '孙权'], zh: '孫權', ch: ['孫', '孙'], born: 182, died: 252, fac: 'sun',
      life: {
        '184': ['xiapi', '182年生于下邳，当时父亲孙坚任下邳丞。孙坚此时随朱儁讨伐黄巾，以勇猛闻名。', 'Born in 182 at Xiapi, where his father Sun Jian was an assistant magistrate. Sun Jian is now fighting the Yellow Turbans under Zhu Jun and making his name.'],
        '190': ['shu', '父亲孙坚随关东联军讨伐董卓，兄长孙策把家安置在庐江舒县，与周瑜结为好友。', 'His father joins the war against Dong Zhuo, and his elder brother Sun Ce settles the family at Shu in Lujiang, where Sun Ce befriends Zhou Yu.'],
        '191': ['shu', '孙坚在阳人大破董卓军，攻入洛阳，随后奉袁术之命攻打刘表，在襄阳附近中伏身亡。孙策年仅十七。', 'Sun Jian beats Dong Zhuo at Yangren and enters Luoyang, then, sent by Yuan Shu against Liu Biao, is ambushed and killed near Xiangyang. Sun Ce is seventeen.'],
        '195': ['wu', '兄长孙策从袁术处借兵渡江，横扫江东，孙权随兄征战。', 'Sun Ce borrows troops from Yuan Shu and conquers the south-east; Sun Quan goes with him.'],
        '196': ['yangxian', '十五岁时被任命为阳羡县长。', 'At fifteen he is made head of Yangxian county.'],
        '200': ['wu', '孙策被许贡门客刺杀，临终对他说：“举江东之众，决机于两陈之间，与天下争衡，卿不如我；举贤任能，各尽其心，以保江东，我不如卿。”十八岁的孙权继位，张昭、周瑜辅佐。', 'Sun Ce is killed by retainers of Xu Gong. Dying, he tells his brother: “In leading the armies of the south to decide things on the battlefield, you are not my equal; in finding able men and getting the best from them to hold the south, I am not yours.” Sun Quan, 18, succeeds him with Zhang Zhao and Zhou Yu at his side.'],
        '207': ['chaisang', '再次征讨杀父仇人黄祖，掳其百姓而还。', 'He attacks Huang Zu, the man whose troops killed his father, and carries off his people.'],
        '208': ['chaisang', '春天攻破江夏，斩黄祖。曹操来书威胁，张昭等人主张迎降，鲁肃、周瑜力主抗战。裴注引《江表传》，孙权拔刀砍案说：“诸将吏敢复有言当迎操者，与此案同！”他派周瑜、程普率三万人西上，在赤壁击败曹操。', 'In spring he takes Jiangxia and kills Huang Zu. When Cao Cao’s threatening letter arrives, Zhang Zhao and others want to submit; Lu Su and Zhou Yu argue for war. According to a source quoted by Pei, he cuts his desk with his sword: “Anyone who speaks again of welcoming Cao Cao will end like this desk!” He sends Zhou Yu and Cheng Pu with 30,000 men, and they win at Red Cliffs.'],
        '209': ['hefei', '亲率大军围攻合肥百余日，未能攻克。', 'He besieges Hefei for over a hundred days without taking it.'],
        '210': ['jingkou', '周瑜病逝，鲁肃接任。他派步骘为交州刺史，士燮兄弟归附。', 'Zhou Yu dies and Lu Su takes over. He sends Bu Zhi to govern Jiao, and Shi Xie’s family submits.'],
        '212': ['jianye', '将治所迁到秣陵，修筑石头城，改名建业。', 'He moves his seat to Moling, builds the Stone Fort and renames the city Jianye.'],
        '213': ['ruxu', '在濡须抵挡曹操大军月余，曹操退兵。', 'At Ruxu he holds off Cao Cao for a month until Cao Cao withdraws.'],
        '215': ['hefei', '派吕蒙夺取长沙三郡后与刘备讲和。随即亲率十万人围攻合肥，撤退时被张辽突袭，在逍遥津几乎被擒。', 'After Lü Meng takes three commanderies he makes peace with Liu Bei, then besieges Hefei with 100,000 men. As he withdraws, Zhang Liao’s charge nearly captures him at Xiaoyao Ford.'],
        '217': ['ruxu', '曹操再攻濡须，他派徐详请降，两家重修婚约。鲁肃去世，吕蒙接任。', 'When Cao Cao attacks Ruxu again he sends Xu Xiang to offer submission and the two houses renew a marriage pact. Lu Su dies and Lü Meng succeeds him.'],
        '219': ['jiangling', '他暗中向曹操表示愿讨伐关羽，派吕蒙“白衣摇橹”袭取江陵、公安，又派陆逊攻取宜都。关羽在临沮被擒，与其子关平一同被杀。不久吕蒙病逝。', 'He secretly offers Cao Cao to attack Guan Yu, and Lü Meng’s men, dressed as merchants, take Jiangling and Gong’an while Lu Xun takes Yidu. Guan Yu and his son Guan Ping are captured at Linju and executed. Lü Meng dies soon after.'],
        '221': ['wuchang', '迁都鄂县，改名武昌。向魏称臣，受封吴王。222年陆逊在夷陵大破刘备；同年他与魏决裂，改元黄武。', 'He moves his capital to E and renames it Wuchang, declares himself Wei’s vassal and is made King of Wu. In 222 Lu Xun destroys Liu Bei at Yiling, and he breaks with Wei.'],
        '229': ['jianye', '四月在武昌称帝，秋天迁都建业，与蜀汉约定中分天下。', 'He becomes emperor at Wuchang in the fourth month and moves to Jianye in the autumn, agreeing with Shu how to divide the world between them.'],
        '234': ['hefei', '配合诸葛亮北伐，亲率十万人攻打合肥新城，无功而返。', 'In concert with Zhuge Liang he attacks the new fort at Hefei with 100,000 men, without success.'],
        '238': ['jianye', '他晚年猜忌日深，宠信校事吕壹，大臣多受迫害，后来他杀吕壹并向群臣致歉。', 'Growing suspicious in old age, he lets the inspector Lü Yi persecute officials, then has him executed and apologises to his ministers.'],
        '251': ['jianye', '太子孙和与鲁王孙霸争储（“二宫之争”），朝臣分裂，陆逊因受斥责忧愤而死（245年）。250年他废孙和、赐死孙霸，立幼子孙亮。252年四月去世，年七十一（虚岁）。', 'The struggle between his heir Sun He and Sun Ba, Prince of Lu, splits the court; Lu Xun dies in 245 after being rebuked. In 250 he deposes Sun He, orders Sun Ba to kill himself and names his youngest son Sun Liang. He dies in the fourth month of 252.', 1],
        '263': [null, '吴国在他的子孙治下继续存在，此时出兵救蜀，未及而蜀已亡。', 'Wu sends troops to help Shu, too late.'],
        '280': [null, '其孙孙皓投降，吴国自229年称帝起立国五十一年而亡。他开发的江南日后成为六朝的核心。', 'His grandson Sun Hao surrenders; Wu ends 51 years after he took the throne. The south he built up became the heartland of the Six Dynasties.']
      }
    },
    zhuge: {
      n: ['Zhuge Liang', '诸葛亮'], zh: '諸葛亮', ch: ['亮', '亮'], born: 181, died: 234, fac: 'liubei',
      life: {
        '184': ['langya', '181年生于琅琊阳都，父亲诸葛珪曾任泰山郡丞，在他幼年时去世。', 'Born in 181 at Yangdu, Langya. His father Zhuge Gui, an assistant administrator of Taishan, died when he was a child.'],
        '190': ['langya', '他和兄弟姐妹由叔父诸葛玄抚养。', 'He and his siblings are raised by their uncle Zhuge Xuan.'],
        '194': ['yuzhang', '曹操屠戮徐州。叔父诸葛玄被袁术任命为豫章太守，带他和弟弟诸葛均南下赴任；后来朝廷另派太守，诸葛玄转投荆州刘表。', 'Cao Cao ravages Xu. His uncle, appointed Administrator of Yuzhang by Yuan Shu, takes him and his younger brother south; when the court sends a rival appointee, the uncle goes on to Liu Biao in Jing.'],
        '197': ['longzhong', '叔父去世后，他在襄阳城西二十里的隆中躬耕，好为《梁父吟》，“每自比于管仲、乐毅，时人莫之许也”。', 'After his uncle dies he farms at Longzhong, twenty li west of Xiangyang, fond of singing the Liangfu ballad, “always comparing himself to Guan Zhong and Yue Yi, though few agreed.”'],
        '201': ['longzhong', '只有徐庶、崔州平等少数好友认可他。裴注引《襄阳记》说，名士庞德公称他为“卧龙”。', 'Only a few friends such as Xu Shu and Cui Zhouping take him seriously. According to a source quoted by Pei, the recluse Pang Degong calls him the “sleeping dragon.”'],
        '207': ['longzhong', '刘备三顾茅庐。他提出《隆中对》：曹操“已拥百万之众，挟天子而令诸侯，此诚不可与争锋”；孙权据有江东已历三世，“可以为援而不可图”；应先取荆、益二州，结好孙权，待天下有变，再两路北伐。', 'Liu Bei calls three times. Zhuge Liang lays out his plan: Cao Cao “already has a million men and holds the emperor; you cannot fight him head-on.” Sun Quan’s family has held the south for three generations; “he can be an ally, not a target.” Take Jing and Yi first, make friends with Sun Quan, and when the world shifts, march north on two fronts.'],
        '208': ['chaisang', '长坂败后，他自请出使江东，在柴桑说服孙权联合抗曹。', 'After Changban he volunteers to go to Sun Quan and persuades him at Chaisang to fight Cao Cao.'],
        '209': ['linzheng', '任军师中郎将，驻临烝，督零陵、桂阳、长沙三郡，征收赋税以充军需。', 'As General of the Household Advising the Army he is stationed at Linzheng, running Lingling, Guiyang and Changsha and collecting taxes for the army.'],
        '211': ['gongan', '刘备入蜀，他与关羽留守荆州。', 'When Liu Bei goes west he stays behind with Guan Yu to hold Jing.'],
        '214': ['chengdu', '与张飞、赵云率军溯江而上，分定郡县，与刘备会师围成都。成都平定后任军师将军，署左将军府事，刘备出征时他镇守成都，“足食足兵”。', 'With Zhang Fei and Zhao Yun he leads an army up the Yangtze, takes the counties on the way and joins Liu Bei before Chengdu. Afterwards, as General Directing the Army, he runs Liu Bei’s headquarters and keeps Chengdu supplied with “enough food and enough soldiers” whenever Liu Bei is away.'],
        '221': ['chengdu', '刘备称帝，任丞相、录尚书事。', 'When Liu Bei becomes emperor he is made Chancellor with charge of the secretariat.'],
        '223': ['baidi', '赶到白帝城接受托孤，涕泣说：“臣敢竭股肱之力，效忠贞之节，继之以死！”此后开府治事，蜀汉政事无论大小都由他决断。他派邓芝出使东吴，恢复了联盟。', 'He hurries to Baidi to receive Liu Bei’s charge and replies in tears: “I will give my all, with loyalty and integrity, until death.” From then on every decision in Shu, great or small, is his. He sends Deng Zhi to Wu and restores the alliance.'],
        '225': ['jieting', '225年春亲征南中，秋天平定，“军资所出，国以富饶”。227年上《出师表》，率军进驻汉中。228年春出祁山，天水、南安、安定三郡响应，但先锋马谡在街亭违背调度、舍水上山，被张郃大败。他挥泪斩马谡，上疏自贬三等。冬天出散关围陈仓，因粮尽退兵。', 'In 225 he campaigns in the south and has it pacified by autumn, its resources now enriching the state. In 227 he submits his memorial and moves to Hanzhong. In spring 228 he marches out by Qishan and three commanderies go over to him, but his vanguard commander Ma Su disobeys orders, camps on a hill away from water and is routed by Zhang He at Jieting. He has Ma Su executed in tears and asks to be demoted three grades. In winter he besieges Chencang and withdraws when food runs out.'],
        '229': ['hanzhong', '派陈式攻取武都、阴平二郡，官复丞相。孙权称帝后，他力排众议，遣使祝贺。', 'He sends Chen Shi to take Wudu and Yinping and is restored as Chancellor. When Sun Quan takes the throne he overrides objections and sends congratulations.'],
        '234': ['wuzhang', '231年再出祁山，以木牛运粮。负责供粮的李严因粮草不继，派人传旨召他回军，等他退兵后又假装吃惊；诸葛亮查明后上表将李严废为平民。退兵途中，蜀军射杀了追击的魏将张郃。234年春率十万大军出斜谷，以流马运粮，在五丈原分兵屯田，作长久之计。司马懿坚守不出，他送去妇人衣服相激（见裴注）。八月病逝于军中，年五十四（虚岁）。遗命葬于定军山，“因山为坟，冢足容棺，敛以时服，不须器物”。', 'In 231 he marches by Qishan again, moving grain on wooden oxen. When supplies run short, Li Yan, in charge of the grain, sends word calling him back, then feigns surprise that he has withdrawn; Zhuge Liang exposes him and has him stripped of office. On the way back his archers kill the pursuing Wei general Zhang He. In spring 234 he leads 100,000 men out by the Xie valley, with gliding horses for supply, and sets soldiers to farm on the Wuzhang Plains for a long campaign. Sima Yi will not come out; Zhuge Liang sends him women’s clothes to goad him (Pei’s notes). In the eighth month he dies in camp. He asks to be buried on Dingjun Mountain in a grave just big enough for the coffin, in everyday clothes, with nothing else.', 1],
        '238': [null, '蒋琬、费祎相继主政，延续他的方针，暂停大规模北伐。', 'Jiang Wan and then Fei Yi lead Shu, keeping his policies but pausing the great campaigns.'],
        '263': [null, '他的儿子诸葛瞻、孙子诸葛尚在绵竹抵抗邓艾，双双战死。', 'His son Zhuge Zhan and grandson Zhuge Shang die fighting Deng Ai at Mianzhu.'],
        '280': [null, '陈寿评他“识治之良才，管、萧之亚匹”，但“将略非其所长”；小说则把他写成呼风唤雨的半仙。', 'Chen Shou called him a great statesman, the equal of the ancient ministers, but said generalship was not his strength. The novel made him a near-magician.']
      }
    },
    guanyu: {
      n: ['Guan Yu', '关羽'], zh: '關羽', ch: ['關', '关'], born: null, died: 220, fac: 'liubei',
      life: {
        '184': ['zhuo', '河东解县人，因故逃亡到涿郡，加入刘备的队伍。史书没有记载他的生年。', 'From Xie county in Hedong, he fled to Zhuo for reasons the history does not give and joined Liu Bei. His birth year is not recorded.'],
        '191': ['pingyuan', '刘备任平原相，以他和张飞为别部司马，分统部曲。史书说三人“寝则同床，恩若兄弟”，而在大庭广众之中，他和张飞“侍立终日”。', 'When Liu Bei becomes chancellor of Pingyuan, he and Zhang Fei command separate detachments. The history says the three “slept in one bed, close as brothers,” while in public he and Zhang Fei stood beside Liu Bei all day.'],
        '194': ['xiapi', '随刘备入主徐州。', 'He follows Liu Bei to Xu.'],
        '198': ['xiapi', '随刘备、曹操围攻下邳。裴注引《蜀记》说，他请求曹操在城破后把秦宜禄的妻子许给他，曹操见其貌美，自己纳了她。', 'He besieges Xiapi with Liu Bei and Cao Cao. A source quoted by Pei says he asked Cao Cao for the wife of Qin Yilu once the city fell, and Cao Cao, seeing how beautiful she was, took her himself.'],
        '199': ['xiapi', '刘备袭杀车胄后，让他镇守下邳，代理太守。', 'After Liu Bei kills Che Zhou, he is left to hold Xiapi as acting administrator.'],
        '200': ['baima', '曹操东征，他兵败投降，被拜为偏将军，“礼之甚厚”。白马之战，他望见颜良的麾盖，策马冲入万军之中刺杀颜良、斩其首而还，被封为汉寿亭侯。此后他尽封曹操所赐，留书告辞，回到刘备身边。曹操说：“彼各为其主，勿追也。”', 'When Cao Cao attacks, he is captured and made a general, treated with great honour. At Baima he spots Yan Liang’s parasol, rides into the midst of ten thousand men, stabs him and comes back with his head; he is made Marquis of Hanshou. Then he seals up all Cao Cao’s gifts, leaves a letter of farewell and goes back to Liu Bei. Cao Cao says: “Each man serves his own master. Do not pursue him.”'],
        '201': ['xinye', '随刘备依附刘表。', 'He goes with Liu Bei to Liu Biao.'],
        '208': ['jiangling', '刘备南撤时，他率数百艘战船沿汉水而下，在汉津接应溃败的刘备，一同到达夏口。', 'He leads several hundred boats down the Han, meets the routed Liu Bei at Hanjin and takes him to Xiakou.'],
        '209': ['jiangling', '任襄阳太守、荡寇将军，驻守长江以北。', 'As Administrator of Xiangyang and General Who Sweeps Away Bandits he holds the north bank of the Yangtze.'],
        '214': ['jiangling', '刘备入蜀后他“董督荆州事”。马超来降，他写信问诸葛亮马超的才能可与谁相比，诸葛亮回信说马超可与张飞并驾齐驱，“犹未及髯之绝伦逸群也”，他看了十分高兴。他曾中流矢，臂骨中毒，请医生刮骨去毒，“时羽适请诸将饮食相对，臂血流离，盈于盘器，而羽割炙引酒，言笑自若”。', 'With Liu Bei in Yi, he runs Jing. When Ma Chao joins them he writes to ask Zhuge Liang how Ma Chao compares; Zhuge Liang replies that Ma Chao is Zhang Fei’s equal “but not the match of the Beard, who is beyond compare,” which delights him. An old arrow wound having poisoned his arm, he has a doctor cut it open and scrape the bone while he dines with his officers, “blood running into the dishes, carving meat and drinking, laughing and talking as usual.”'],
        '215': ['yiyang', '孙刘争夺荆州，他与鲁肃在益阳对峙。鲁肃邀他相见，双方兵马停在百步之外，诸将只带单刀赴会，鲁肃当面责备刘备借地不还（《鲁肃传》）。', 'With Sun and Liu at odds over Jing, he faces Lu Su at Yiyang. They meet with their troops a hundred paces back and the officers carrying only swords, and Lu Su rebukes Liu Bei for not returning the land (Biography of Lu Su).'],
        '219': ['maicheng', '刘备称汉中王，拜他为前将军，假节钺。七月他北攻樊城，八月大雨，汉水泛滥，于禁七军被淹，于禁投降，庞德被斩，“羽威震华夏”，曹操一度商议迁都避其锋芒。但他与镇守江陵的糜芳、公安的士仁不和，吕蒙袭取二城时二人投降。他军心瓦解，退守麦城，十二月在临沮被吴将马忠擒获，与其子关平一同被杀。', 'Liu Bei, now King of Hanzhong, makes him General of the Van with full powers. In the seventh month he attacks Fancheng; in the eighth heavy rain floods the Han, Yu Jin’s seven armies are drowned, Yu Jin surrenders and Pang De is executed. “His fame shook the realm,” and Cao Cao even considered moving the capital. But he was on bad terms with Mi Fang at Jiangling and Shi Ren at Gong’an, and when Lü Meng comes both surrender. His army melts away; he falls back on Maicheng and in the twelfth month is captured at Linju by the Wu officer Ma Zhong and executed with his son Guan Ping.', 1],
        '221': [null, '刘备为他复仇，起兵伐吴，在夷陵大败。', 'Liu Bei goes to war with Wu to avenge him and is crushed at Yiling.'],
        '263': [null, '260年刘禅追谥他为壮缪侯。成都陷落时，据裴注引《蜀记》，庞德之子庞会诛灭了关氏家族。', 'In 260 Liu Shan gave him the posthumous title Marquis Zhuangmou. When Chengdu falls, according to a source quoted by Pei, Pang De’s son Pang Hui wipes out the Guan family.'],
        '280': [null, '此后历代不断加封，明清时被尊为“关圣帝君”，至今在华人世界作为忠义与财神受到供奉。陈寿评他“刚而自矜”，以短取败。', 'Later dynasties kept raising his titles until he became the god Guan Di, still worshipped across the Chinese world for loyalty and wealth. Chen Shou judged him “unbending and proud,” flaws that brought him down.']
      }
    },
    simayi: {
      n: ['Sima Yi', '司马懿'], zh: '司馬懿', ch: ['懿', '懿'], born: 179, died: 251, fac: 'cao',
      life: {
        '184': ['wen', '179年生于河内温县一个世代为官的家族，父亲司马防曾任京兆尹，兄弟八人皆有才名，号称“司马八达”。', 'Born in 179 in Wen county, Henei, to a family of officials; his father Sima Fang was governor of the capital region, and he and his seven brothers were known as the “eight Da of the Sima.”'],
        '201': ['wen', '据《晋书·宣帝纪》，曹操任司空时征辟他，他不愿屈节，假称患风痹，卧床不起。曹操派人夜里去刺探，他坚卧不动。', 'According to the Book of Jin, when Cao Cao summoned him he did not want to serve and pretended to be paralysed; when Cao Cao sent someone to check by night, he lay perfectly still.'],
        '208': ['ye', '曹操任丞相后再次征召，并说“若复盘桓，便收之”，他只好就任文学掾，随后被安排与曹丕交游。', 'When Cao Cao becomes Chancellor he summons him again with the warning “if he dawdles, arrest him.” He takes the post of literary clerk and is placed in Cao Pi’s circle.'],
        '215': ['nanzheng', '随曹操征张鲁，劝他乘胜取蜀，曹操说：“人苦无足，既得陇右，复欲得蜀！”（《晋书·宣帝纪》）', 'With Cao Cao against Zhang Lu, he urges him to press on into Shu. Cao Cao replies: “Men are never satisfied. Having got Longyou, now you want Shu!” (Book of Jin).'],
        '217': ['ye', '曹丕被立为太子，他任太子中庶子，深受信任。', 'When Cao Pi becomes Crown Prince he joins his household as an adviser and wins his trust.'],
        '219': ['luoyang', '关羽围樊城，曹操想迁都避锋，他与蒋济劝阻，建议许诺割江南之地给孙权，让孙权从背后袭击关羽。', 'With Guan Yu besieging Fancheng and Cao Cao thinking of moving the capital, he and Jiang Ji argue against it and suggest offering Sun Quan land south of the Yangtze to attack Guan Yu from behind.'],
        '220': ['luoyang', '曹丕即位称帝，他任尚书，后转督军、御史中丞。', 'When Cao Pi takes the throne he becomes a Master of Writing, then an army supervisor and Palace Assistant Imperial Clerk.'],
        '225': ['wan', '226年曹丕临终，以他和曹真、陈群、曹休为辅政大臣。曹叡即位后他坐镇宛城，督荆、豫二州。228年新城太守孟达谋叛归蜀，他不待奏报，倍道兼行，八日赶到城下，十六日破城斩孟达。', 'Dying in 226, Cao Pi names him regent alongside Cao Zhen, Chen Qun and Cao Xiu. Under Cao Rui he commands Jing and Yu from Wan. In 228 Meng Da of Xincheng plans to defect to Shu; without waiting for orders he marches day and night, reaches the city in eight days, and takes it and kills Meng Da in sixteen.'],
        '234': ['wuzhang', '231年起接替曹真抵御诸葛亮。在五丈原他坚守不战，诸葛亮送来妇人衣服相激，他上表请战，明帝派辛毗持节阻止，他借此按兵不动。诸葛亮死后蜀军撤退，他追击时见蜀军回旗鸣鼓，急忙退兵，百姓因此说“死诸葛走生仲达”（裴注引《汉晋春秋》）。', 'From 231 he takes over from Cao Zhen against Zhuge Liang. At the Wuzhang Plains he will not fight; when Zhuge Liang sends him women’s clothes, he asks permission to attack, and the emperor sends Xin Pi to forbid it, which suits him. After Zhuge Liang dies, he pursues the retreating army, sees it turn with banners and drums, and pulls back, giving rise to the saying “a dead Zhuge put a live Zhongda to flight” (Pei, quoting the Han Jin Chunqiu).'],
        '238': ['xiangping', '率四万人远征辽东，以霖雨为掩护围困襄平，城破后斩公孙渊父子，并屠杀城中十五岁以上男子七千余人（《晋书·宣帝纪》）。239年曹叡临终，他与曹爽同受遗诏辅政。', 'He leads 40,000 men to Liaodong, besieges Xiangping through the summer rains, kills Gongsun Yuan and his son, and massacres over seven thousand men of fifteen and older in the city (Book of Jin). In 239 the dying Cao Rui makes him co-regent with Cao Shuang.'],
        '249': ['luoyang', '他多年称病在家，示弱于曹爽。正月趁曹爽兄弟随曹芳出城谒高平陵，与儿子司马师、司马昭发动政变，占据洛阳，指洛水为誓劝曹爽投降。曹爽交出兵权后，不久即被诛灭三族。', 'For years he has stayed home claiming illness, looking harmless to Cao Shuang. In the first month, with Cao Shuang and his brothers outside the city at the Gaoping tomb, he and his sons Sima Shi and Sima Zhao seize Luoyang, and he swears by the Luo River that Cao Shuang will be spared if he surrenders. Cao Shuang gives up his command and is soon executed with his whole clan.'],
        '251': ['luoyang', '太尉王凌在寿春谋立楚王曹彪，他率军突袭，王凌自杀。八月他在洛阳去世，年七十三（虚岁）。', 'Wang Ling plots at Shouchun to make Cao Biao emperor; he marches suddenly against him and Wang Ling kills himself. He dies at Luoyang in the eighth month.', 1],
        '263': [null, '他的次子司马昭主持伐蜀，消灭蜀汉。', 'His second son Sima Zhao directs the conquest of Shu.'],
        '265': [null, '孙子司马炎代魏称帝，建立晋朝，追尊他为宣皇帝。', 'His grandson Sima Yan takes the throne from Wei, founds Jin, and names him Emperor Xuan.'],
        '280': [null, '晋灭吴，统一天下。三国最后的赢家，不是曹、刘、孙，而是司马氏。', 'Jin conquers Wu and reunites China. The winner of the Three Kingdoms is not Cao, Liu or Sun, but the Sima family.']
      }
    }
  }
};
